/**
 * `MapKeyboard` — a single keyboard interaction for `<mapml-viewer>`, mirroring
 * MapML.js's one `L.Map.Keyboard` handler (OpenLayers ships two split
 * interactions, `KeyboardPan` + `KeyboardZoom`, which we replace here).
 *
 * Behaviour:
 *   - Arrow keys pan. Shift+Arrow pans a coarse "page" step; Ctrl+Arrow pans a
 *     fine step. Alt+Arrow is reserved for history back/forward (context menu)
 *     and Meta is left to the browser, so both are ignored here.
 *   - `+`/`=` zoom in, `-`/`_` zoom out, snapping to whole zoom levels the way
 *     Leaflet/MapML.js do (OpenLayers' KeyboardZoom leaves fractional zooms).
 *
 * The interaction only acts when the event target is not an editable field, so
 * typing into inputs (e.g. the layer control) is never intercepted.
 */
import Interaction, { pan } from 'ol/interaction/Interaction.js';
import EventType from 'ol/events/EventType.js';
import { rotate as rotateCoordinate } from 'ol/coordinate.js';

// True if the key event originated in an editable control (INPUT/SELECT/
// TEXTAREA/contenteditable). OL's `targetNotEditable` reads `event.target`,
// but our map lives in the viewer's shadow root, so OL attaches its keyboard
// listener to the host — a keydown from a shadow-hosted <select> (e.g. the
// layer control's <map-select>) is retargeted to the host and would look
// non-editable. Read the real innermost target from `composedPath()` instead
// so native arrow-key selection in those controls is never intercepted.
function eventFromEditable(keyEvent) {
  const path =
    typeof keyEvent.composedPath === 'function' ? keyEvent.composedPath() : null;
  const target = path && path.length ? path[0] : keyEvent.target;
  const tagName = target && target.tagName;
  return (
    tagName === 'INPUT' ||
    tagName === 'SELECT' ||
    tagName === 'TEXTAREA' ||
    (target && target.isContentEditable === true)
  );
}

// [dx, dy] unit vectors in view space (y up).
const ARROW_VECTORS = {
  ArrowUp: [0, 1],
  ArrowDown: [0, -1],
  ArrowLeft: [-1, 0],
  ArrowRight: [1, 0]
};
const ZOOM_IN_KEYS = ['+', '='];
const ZOOM_OUT_KEYS = ['-', '_'];

const BASE_PAN_PIXELS = 128;
const PAGE_PAN_MULTIPLIER = 3; // Shift+Arrow: coarse pan
const FINE_PAN_DIVISOR = 4; // Ctrl+Arrow: fine pan

export class MapKeyboard extends Interaction {
  constructor(options = {}) {
    super();
    this._panPixels = options.panPixels ?? BASE_PAN_PIXELS;
    this._duration = options.duration ?? 100;
  }

  /**
   * @param {import('ol/MapBrowserEvent.js').default} mapBrowserEvent
   * @return {boolean} `false` to stop propagation once handled.
   * @override
   */
  handleEvent(mapBrowserEvent) {
    if (mapBrowserEvent.type !== EventType.KEYDOWN) {
      return true;
    }
    const keyEvent = mapBrowserEvent.originalEvent;
    if (eventFromEditable(keyEvent)) {
      return true;
    }
    const key = keyEvent.key;

    // Pan. Meta/Alt combinations are left alone (browser / history shortcuts).
    if (ARROW_VECTORS[key] && !keyEvent.altKey && !keyEvent.metaKey) {
      this._pan(mapBrowserEvent.map, key, keyEvent);
      keyEvent.preventDefault();
      return false;
    }

    // Zoom. Only the unmodified keys zoom, so Ctrl/Meta +/- stays the browser's.
    if (!keyEvent.ctrlKey && !keyEvent.metaKey && !keyEvent.altKey) {
      if (ZOOM_IN_KEYS.includes(key)) {
        this._zoom(mapBrowserEvent.map, 1);
        keyEvent.preventDefault();
        return false;
      }
      if (ZOOM_OUT_KEYS.includes(key)) {
        this._zoom(mapBrowserEvent.map, -1);
        keyEvent.preventDefault();
        return false;
      }
    }
    return true;
  }

  _pan(map, key, keyEvent) {
    const view = map.getView();
    let pixels = this._panPixels;
    if (keyEvent.shiftKey) {
      pixels *= PAGE_PAN_MULTIPLIER;
    } else if (keyEvent.ctrlKey) {
      pixels /= FINE_PAN_DIVISOR;
    }
    const mapUnitsDelta = view.getResolution() * pixels;
    const [dx, dy] = ARROW_VECTORS[key];
    const delta = [dx * mapUnitsDelta, dy * mapUnitsDelta];
    rotateCoordinate(delta, view.getRotation());
    pan(view, delta, this._duration);
  }

  _zoom(map, delta) {
    const view = map.getView();
    const current = view.getZoom();
    if (current === undefined) {
      return;
    }
    // Snap to whole zoom levels so keyboard zoom matches the tile pyramid.
    view.animate({
      zoom: Math.round(current) + delta,
      duration: this._duration
    });
  }
}
