/**
 * `<map-layer>` — a named, toggleable layer. Named `HTMLLayerElement` to match
 * MapML.js, where a `<map-layer>` *is* a Leaflet `LayerGroup`; here it owns an
 * `ol/layer/Group` added to the map. Child `<map-extent>` groups and tile
 * layers are pushed into it in DOM order (index === render z-order).
 *
 * `checked` drives group visibility; `opacity` drives group opacity. The layer
 * control markup/events are built by `getLayerControlHTML()` (ported from
 * MapML.js's createLayerControlForLayer.js).
 */
/* global M */
import LayerGroup from 'ol/layer/Group.js';
import { createLayerControlForLayer } from './mapml/elementSupport/layers/createLayerControlForLayer.js';
import { calculatePosition } from './mapml/elementSupport/layers/calculatePosition.js';
import { MapFeatureLayer } from './mapml/layers/MapFeatureLayer.js';
import { MapTileLayer } from './mapml/layers/MapTileLayer.js';
import { Util } from './mapml/utils/Util.js';
import { toBounds as bounds } from './mapml/geometry/Bounds.js';

export class HTMLLayerElement extends HTMLElement {
  static get observedAttributes() {
    return ['label', 'checked', 'hidden', 'opacity', 'src'];
  }

  constructor() {
    super();
    this._settingsExpanded = false;
    // Dedup key for the "no projection assigned" warning (see getProjection).
    this.loggedMessages = new Set();
    this._createReadyPromise();
  }

  // Deferred resolved once the layer (and, for a remote `src`, its grafted
  // shadow content) is ready; rejected on fetch/parse error. Mirrors MapML.js
  // layer.js whenReady()/`_fetchError`.
  _createReadyPromise() {
    this._readyPromise = new Promise((resolve, reject) => {
      this._readyResolve = resolve;
      this._readyReject = reject;
    });
    // Swallow unhandled-rejection noise; callers that care attach handlers.
    this._readyPromise.catch(() => {});
  }

  whenReady() {
    return this._readyPromise;
  }

  // The layer's accessible name. Once the layer has initialised, this is the
  // name resolved by `_setLayerTitle` (an inline/remote `<map-title>`, else the
  // `label` attribute); before that it falls back to the raw attribute. The
  // setter reflects to the `label` attribute, which `attributeChangedCallback`
  // routes through `setName` (a no-op when a `<map-title>` owns the name).
  // Ported from MapML.js layer.js `label`/MapLayer.js `getName`/`setName`.
  get label() {
    if (this._hasConnected) return this.getName() || '';
    return this.getAttribute('label') || '';
  }
  set label(val) {
    if (val) {
      this.setAttribute('label', val);
    }
  }

  // Whether the accessible name is fixed by a `<map-title>` and therefore
  // cannot be overridden via the `label` attribute/setter. Ported from
  // MapML.js MapLayer.js titleIsReadOnly.
  titleIsReadOnly() {
    return !!this._titleIsReadOnly;
  }

  getName() {
    return this._title;
  }

  // Update the accessible name unless a `<map-title>` owns it, then refresh the
  // layer control. Ported from MapML.js MapLayer.js setName.
  setName(newName) {
    if (!this.titleIsReadOnly()) {
      this._title = newName;
      this._notifyLayersChanged();
    }
  }

  // A remote MapML document to graft into this layer's shadow root. When set,
  // the layer's content (map-meta/map-extent/map-feature/map-link/map-style)
  // is fetched and mirrored under `this.shadowRoot`. Ported from MapML.js
  // layer.js.
  get src() {
    return this.getAttribute('src');
  }
  set src(value) {
    if (value) {
      this.setAttribute('src', value);
    } else {
      this.removeAttribute('src');
    }
  }

  // The layer's extent envelope (pcrs/gcrs/tcrs/tilematrix corners + zoom),
  // ported from MapML.js layer.js. Bounds are (re)derived on every read.
  get extent() {
    this._calculateBounds();
    return this.bounds
      ? Object.assign(
          Util._convertAndFormatPCRS(
            this.bounds,
            window.M[this.getProjection()],
            this.getProjection()
          ),
          { zoom: this.zoomBounds }
        )
      : null;
  }

  get checked() {
    return this.hasAttribute('checked');
  }
  set checked(value) {
    if (value) {
      this.setAttribute('checked', '');
    } else {
      this.removeAttribute('checked');
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) {
      return;
    }
    if (name === 'label') {
      // Ignore the initial attribute upgrade; `_setLayerTitle` resolves the
      // name once, then runtime writes flow through `setName`.
      if (this._hasConnected) {
        this.setName(newValue);
      }
    } else if (name === 'checked') {
      this._layerGroup?.setVisible(this.checked);
    } else if (name === 'hidden') {
      // `hidden` toggles the layer's presence in the layer control (rendering
      // follows `checked`, not `hidden`); rebuild it. Ported from MapML.js
      // layer.js (addOrUpdateOverlay / removeLayer).
      this._notifyLayersChanged();
    } else if (name === 'opacity' && newValue !== null) {
      this._layerGroup?.setOpacity(Number(newValue));
    } else if (name === 'src') {
      // Runtime `src` change (e.g. the layer-control alternate-style radio
      // rewrites it): tear down and reload. Ported from MapML.js layer.js.
      // The projection-negotiation swap (see _handleChangeProjection) sets this
      // flag so it can reload on the SAME pending readyPromise instead.
      if (this._hasConnected && !this._suppressSrcReload) {
        void this._reload();
      }
    }
  }

  // Reflect opacity to the group (called by the layer-control opacity slider).
  setOpacity(value) {
    this.setAttribute('opacity', String(value));
    this._layerGroup?.setOpacity(Number(value));
  }

  // Fit the view to this layer's extent. Ported from MapML.js layer.js
  // `zoomTo`; used by feature link traversal (Util._handleLink) after a new
  // <map-layer src> is appended.
  zoomTo() {
    this._calculateBounds();
    const map = this._viewer?.map;
    if (!this.bounds || !map) return;
    const { min, max } = this.bounds;
    map.getView().fit([min.x, min.y, max.x, max.y], { size: map.getSize() });
    this._viewer._updateMapCenter();
  }

  async connectedCallback() {
    this._viewer = this.closest('mapml-viewer');
    if (!this._viewer) {
      return;
    }
    await this._viewer.whenReady();
    if (!this.isConnected) {
      return;
    }
    // Mark connected up front (matches MapML.js layer.js `#hasConnected`) so
    // runtime attribute changes (notably `src` from an alternate-style pick)
    // act even while the initial remote content is still loading.
    this._hasConnected = true;
    // When the user picks an alternate style in the layer control, swap `src`
    // to the chosen document (its attributeChangedCallback reloads). Ported
    // from MapML.js layer.js `_onAdd`.
    this._setUpChangeStyleListener();
    await this._onAdd();
  }

  _setUpChangeStyleListener() {
    if (this._changeStyleListening) return;
    this._changeStyleListening = true;
    this.addEventListener('changestyle', (e) => {
      e.stopPropagation();
      if (e.detail) {
        this.src = e.detail.src;
      }
    });
  }

  // Load (or re-load) the layer's content into a fresh layer group. Shared by
  // connectedCallback and the runtime `src` reload. Ported from MapML.js
  // layer.js `_onAdd`.
  async _onAdd() {
    this.getLayerGroup();
    try {
      if (this.src) {
        // Remote layer: fetch the MapML document and graft its head/body
        // children into this element's shadow root, then let those grafted
        // custom elements self-register. Ported from MapML.js layer.js _onAdd.
        await this._loadRemoteContent();
      } else {
        // Inline layer: read the accessible name from a child `<map-title>`.
        this._setLayerTitle(this);
      }
      // Projection negotiation: if the layer's content is in a projection other
      // than the map's, either swap to a `rel=alternate` document in the map's
      // projection or (single-layer case) ask the map to change projection.
      // May throw `changeprojection`. Ported from MapML.js layer.js.
      await this.selectAlternateOrChangeProjection();
      this._notifyLayersChanged();
      this._readyResolve();
      // Signal end of layer initialisation (extent/projection metadata ready),
      // re-using the HTMLMediaElement `loadedmetadata` event name. Ported from
      // MapML.js layer.js; authors listen for it before mutating the layer.
      this.dispatchEvent(
        new CustomEvent('loadedmetadata', { detail: { target: this } })
      );
    } catch (error) {
      if (error.message === 'changeprojection') {
        await this._handleChangeProjection(error);
        return;
      }
      this._notifyLayersChanged();
      this._readyReject(error);
    }
  }

  // Resolve a projection mismatch between the layer's content and the map.
  // Path A (implemented): swap to a `rel=alternate` document in the map's
  // projection. Path B (deferred to Phase 12 live projection switching):
  // adopt the layer's projection for the whole map. Ported from MapML.js
  // layer.js selectAlternateOrChangeProjection.
  selectAlternateOrChangeProjection() {
    const mapml = this.src ? this.shadowRoot : this;
    const mapProjection = this.parentElement.projection;
    const selectedAlternate =
      this.getProjection() !== mapProjection &&
      mapml?.querySelector(
        `map-link[rel=alternate][projection=${mapProjection}][href]`
      );
    if (selectedAlternate) {
      const url = new URL(
        selectedAlternate.getAttribute('href'),
        selectedAlternate.getBase()
      ).href;
      throw new Error('changeprojection', { cause: { href: url } });
    }
    const contentProjection = this.getProjection();
    if (
      contentProjection !== mapProjection &&
      this.parentElement.layers.length === 1
    ) {
      throw new Error('changeprojection', {
        cause: { mapprojection: contentProjection }
      });
    }
  }

  // Act on a `changeprojection` throw from selectAlternateOrChangeProjection.
  async _handleChangeProjection(error) {
    const cause = error.cause || {};
    if (cause.href) {
      // Path A: reload from the alternate document (in the map's projection).
      // Swap `src` WITHOUT the attributeChangedCallback reload so the current
      // pending readyPromise resolves once the alternate finishes loading.
      console.log('Changing layer src to: ' + cause.href);
      this._onRemove();
      this._suppressSrcReload = true;
      this.setAttribute('src', cause.href);
      this._suppressSrcReload = false;
      await this._onAdd();
    } else if (cause.mapprojection) {
      // Path B (deferred to Phase 12 live projection switching): reflect the
      // layer's projection onto the viewer. The viewer does not yet re-render
      // on runtime `projection` changes, so this is currently a no-op switch;
      // Phase 12's projection attributeChangedCallback will complete it.
      console.log(
        'Changing map projection to match layer: ' + cause.mapprojection
      );
      this.parentElement.setAttribute('projection', cause.mapprojection);
      this._notifyLayersChanged();
      this._readyResolve();
    }
  }

  // Tear down the layer's rendered content (group, feature vector, grafted
  // shadow content) so it can be reloaded. Ported from MapML.js layer.js
  // `_onRemove`.
  _onRemove() {
    if (this._layerGroup && this._viewer?.map) {
      this._viewer.map.removeLayer(this._layerGroup);
    }
    this._layerGroup = null;
    this._mapmlvectors = null;
    this._layerRegistry = null;
    if (this.shadowRoot) {
      this.shadowRoot.innerHTML = '';
    }
    this._title = undefined;
    this._titleIsReadOnly = false;
    delete this._fetchError;
  }

  // Reload after a runtime `src` change: remove the current content, arm a
  // fresh whenReady, and re-run the add path.
  async _reload() {
    this._onRemove();
    this._createReadyPromise();
    if (this.isConnected) {
      await this._onAdd();
    }
  }

  // Set the layer's accessible name from a `<map-title>` (inline child or
  // remote document), marking it read-only so the `label` attribute can't
  // override it; otherwise fall back to the `label` attribute. Ported from
  // MapML.js MapLayer.js setLayerTitle.
  _setLayerTitle(content) {
    const title = content.querySelector('map-title');
    if (title) {
      this._title = title.textContent.trim();
      this._titleIsReadOnly = true;
    } else if (this.hasAttribute('label')) {
      this._title = this.getAttribute('label').trim();
    }
  }

  // Fetch the remote MapML document referenced by `src`, verify it, graft its
  // <map-head>/<map-body> children into the shadow root, and wait for those
  // grafted extents/features to register. Ported from MapML.js layer.js
  // (_onAdd remote branch + copyRemoteContentToShadowRoot).
  async _loadRemoteContent() {
    if (!this.shadowRoot) {
      this.attachShadow({ mode: 'open' });
    }
    const base = this.baseURI || document.baseURI;
    const url = new URL(this.src, base).href;
    const headers = new Headers();
    headers.append('Accept', 'text/mapml');
    let response;
    try {
      response = await fetch(url, { headers });
    } catch (error) {
      this._fetchError = true;
      throw error;
    }
    if (!response.ok) {
      this._fetchError = true;
      throw new Error(`HTTP error! Status: ${response.status}`);
    }
    const mapmlText = await response.text();
    const content = new DOMParser().parseFromString(mapmlText, 'text/xml');
    if (
      content.querySelector('parsererror') ||
      !content.querySelector('mapml-')
    ) {
      this._fetchError = true;
      console.log('Error fetching layer content:\n\n' + mapmlText + '\n');
      throw new Error('Parser error');
    }
    const mapml = content.querySelector('mapml-');
    this._setLayerTitle(mapml);
    this._copyRemoteContentToShadowRoot(mapml);
    await this._whenElemsReady();
  }

  // Move the remote document's <map-head>/<map-body> children into the shadow
  // root (the MapML document uses the XHTML namespace, so its custom elements
  // upgrade on insertion). Ported from MapML.js layer.js
  // copyRemoteContentToShadowRoot.
  _copyRemoteContentToShadowRoot(mapml) {
    const frag = document.createDocumentFragment();
    const elements = mapml.querySelectorAll('map-head > *, map-body > *');
    for (let i = 0; i < elements.length; i++) {
      frag.appendChild(elements[i]);
    }
    this.shadowRoot.appendChild(frag);
  }

  // Resolve once every grafted <map-extent>/<map-feature> has registered its
  // OL layer (bounds/query templates/rendering ready). Ported from MapML.js
  // layer.js whenElemsReady.
  _whenElemsReady() {
    const target = this.src ? this.shadowRoot : this;
    const elemsReady = [];
    for (const elem of [
      ...target.querySelectorAll('map-extent'),
      ...target.querySelectorAll('map-feature')
    ]) {
      if (elem.whenReady) {
        elemsReady.push(elem.whenReady());
      }
    }
    return Promise.allSettled(elemsReady);
  }

  disconnectedCallback() {
    if (this._layerGroup && this._viewer?.map) {
      this._viewer.map.removeLayer(this._layerGroup);
    }
    this._layerGroup = null;
    this._layerRegistry = null;
    this._notifyLayersChanged();
  }

  _notifyLayersChanged() {
    this._viewer?.dispatchEvent(new CustomEvent('mapml:layerschanged'));
  }

  // Lazily create the group (and attach it to the map) so descendants can
  // obtain it regardless of custom-element upgrade order.
  getLayerGroup() {
    if (this._layerGroup) {
      return this._layerGroup;
    }
    this._viewer = this._viewer || this.closest('mapml-viewer');
    this._layerGroup = new LayerGroup({ layers: [], visible: this.checked });
    this._viewer.map.addLayer(this._layerGroup);
    return this._layerGroup;
  }

  // Lazily create the layer's static-feature vector layer (the `_mapmlvectors`
  // member, MapML.js MapLayer). One per <map-layer>; child <map-feature>
  // elements add their ol/Feature to it. Added to the layer's ol/Group so it
  // inherits visibility/opacity and z-order.
  _getFeatureLayer() {
    if (this._mapmlvectors) {
      return this._mapmlvectors;
    }
    this._mapmlvectors = new MapFeatureLayer({
      projection: this.getProjection(),
      mapEl: this._viewer
    });
    // z-order the feature layer by its <map-feature>'s document position so it
    // renders above/below sibling <map-extent> tile layers in DOM order
    // (mirrors map-extent's `setZIndex(this.position)`). All features share one
    // layer, so the first feature's position stands in for the run.
    const content = this.src ? this.shadowRoot : this;
    const firstFeature = content?.querySelector('map-feature');
    if (firstFeature) {
      this._mapmlvectors.setZIndex(calculatePosition(firstFeature));
    }
    this.getLayerGroup().getLayers().push(this._mapmlvectors);
    return this._mapmlvectors;
  }

  // Whether this layer currently participates in map queries. Ported from
  // MapML.js layer.js `queryable()`: a checked, visible (non-hidden) layer with
  // at least one enabled `<map-link rel=query>` in a checked extent. For a
  // remote `src` layer the extents live in the shadow root.
  queryable() {
    const content = this.src ? this.shadowRoot : this;
    return Boolean(
      content?.querySelector(
        'map-extent[checked] > map-link[rel=query]:not([disabled])'
      ) &&
        this.checked &&
        this._layerGroup &&
        !this.hidden
    );
  }

  // The query templates whose bounds contain `location` (a PCRS Point) at the
  // given zoom. Ported from MapML.js MapLayer.js `getQueryTemplates`.
  getQueryTemplates(location, zoom) {
    const content = this.src ? this.shadowRoot : this;
    const queryLinks = content.querySelectorAll(
      'map-extent[checked] map-link[rel=query]'
    );
    const templates = [];
    for (const link of queryLinks) {
      if (!link._templateVars) continue;
      const zoomBounds = link.getZoomBounds();
      const bounds = link.getBounds();
      const withinZoomBounds =
        zoomBounds.minZoom <= zoom && zoom <= zoomBounds.maxZoom;
      if (bounds.contains(location) && withinZoomBounds) {
        templates.push(link._templateVars);
      }
    }
    return templates;
  }

  // Return a GeoJSON FeatureCollection for this layer's <map-feature>s.
  // Ported from MapML.js layer.js; delegates to Util.mapml2geojson.
  mapml2geojson(options = {}) {
    return Util.mapml2geojson(this, options);
  }

  // Build the per-layer fieldset for the layer control. Delegates to the
  // ported createLayerControlForLayer.js builder (kept standalone to diff 1:1
  // against MapML.js).
  getLayerControlHTML(locale) {
    return createLayerControlForLayer(this, locale);
  }
  // Derive this.bounds (PCRS) + this.zoomBounds from the layer's own
  // <map-meta name="extent"|"zoom"> unioned with the bounds/zoom of every child
  // <map-extent> and the layer's static-feature vector layer (_mapmlvectors).
  // Ported from MapML.js MapLayer.js `_calculateBounds`; the inline-tile
  // (<map-tile>) branch lands when that element is ported. Falls back to the
  // whole projection extent + zoom range for a layer with no bounds source.
  _calculateBounds() {
    delete this.bounds;
    delete this.zoomBounds;
    const projection = this.getProjection();
    // Remote (<map-layer src>) content lives in the shadow root; query it with
    // the `:host >` pseudo. Ported from MapML.js MapLayer.js `_calculateBounds`.
    const content = this.src ? this.shadowRoot : this;
    const pseudo = this.src ? ':host' : ':scope';
    let bnds = content.querySelector(`${pseudo} > map-meta[name=extent][content]`)
      ? Util.getBoundsFromMeta(content)
      : undefined;
    let zoomBounds = content.querySelector(
      `${pseudo} > map-meta[name=zoom][content]`
    )
      ? Util.getZoomBoundsFromMeta(content)
      : undefined;
    const mapExtents = content.querySelectorAll(`${pseudo} > map-extent`);
    let zoomMax, zoomMin, minNativeZoom, maxNativeZoom;
    if (zoomBounds) {
      zoomMax = zoomBounds.maxZoom;
      zoomMin = zoomBounds.minZoom;
      maxNativeZoom = zoomBounds.maxNativeZoom
        ? zoomBounds.maxNativeZoom
        : -Infinity;
      minNativeZoom = zoomBounds.minNativeZoom
        ? zoomBounds.minNativeZoom
        : Infinity;
    }
    for (let i = 0; i < mapExtents.length; i++) {
      mapExtents[i]._calculateBounds();
      let mapExtentLayer = mapExtents[i]._extentGroup;
      if (mapExtentLayer?.bounds) {
        if (!bnds) {
          bnds = bounds(mapExtentLayer.bounds.min, mapExtentLayer.bounds.max);
        } else {
          bnds.extend(mapExtentLayer.bounds);
        }
        if (mapExtentLayer.zoomBounds) {
          if (!zoomBounds) {
            zoomBounds = mapExtentLayer.zoomBounds;
          } else {
            // Extend layer zoombounds
            zoomMax = Math.max(zoomMax, mapExtentLayer.zoomBounds.maxZoom);
            zoomMin = Math.min(zoomMin, mapExtentLayer.zoomBounds.minZoom);
            maxNativeZoom = Math.max(
              maxNativeZoom,
              mapExtentLayer.zoomBounds.maxNativeZoom
            );
            minNativeZoom = Math.min(
              minNativeZoom,
              mapExtentLayer.zoomBounds.minNativeZoom
            );
            zoomBounds.minZoom = zoomMin;
            zoomBounds.maxZoom = zoomMax;
            zoomBounds.minNativeZoom = minNativeZoom;
            zoomBounds.maxNativeZoom = maxNativeZoom;
          }
        }
      }
    }
    // Static sub-layers: union each MapFeatureLayer (_mapmlvectors) and
    // MapTileLayer (a <map-tile> run) bounds/zoom held in the layer's group.
    const featureLayers = this._layerGroup
      ? this._layerGroup
          .getLayers()
          .getArray()
          .filter(
            (l) => l instanceof MapFeatureLayer || l instanceof MapTileLayer
          )
      : [];
    for (const layer of featureLayers) {
      if (layer.layerBounds) {
        if (!bnds) {
          bnds = bounds(layer.layerBounds.min, layer.layerBounds.max);
        } else {
          bnds.extend(layer.layerBounds);
        }
      }
      if (layer.zoomBounds) {
        if (!zoomBounds) {
          zoomBounds = layer.zoomBounds;
          zoomMax = zoomBounds.maxZoom;
          zoomMin = zoomBounds.minZoom;
          maxNativeZoom = zoomBounds.maxNativeZoom ?? -Infinity;
          minNativeZoom = zoomBounds.minNativeZoom ?? Infinity;
        } else {
          zoomMax = Math.max(zoomMax, layer.zoomBounds.maxZoom);
          zoomMin = Math.min(zoomMin, layer.zoomBounds.minZoom);
          maxNativeZoom = Math.max(maxNativeZoom, layer.zoomBounds.maxNativeZoom);
          minNativeZoom = Math.min(minNativeZoom, layer.zoomBounds.minNativeZoom);
          zoomBounds.minZoom = zoomMin;
          zoomBounds.maxZoom = zoomMax;
          zoomBounds.minNativeZoom = minNativeZoom;
          zoomBounds.maxNativeZoom = maxNativeZoom;
        }
      }
    }
    if (bnds) {
      this.bounds = bnds;
    } else {
      let projectionBounds = M[projection].options.bounds;
      this.bounds = bounds(projectionBounds.min, projectionBounds.max);
    }
    // we could get here and zoomBounds might still not be defined (empty layer)
    if (!zoomBounds) zoomBounds = {};
    if (!zoomBounds.minZoom) {
      zoomBounds.minZoom = 0;
    }
    if (!zoomBounds.maxZoom) {
      zoomBounds.maxZoom = M[projection].options.resolutions.length - 1;
    }
    if (zoomBounds.minNativeZoom === Infinity) {
      zoomBounds.minNativeZoom = zoomBounds.minZoom;
    }
    if (zoomBounds.maxNativeZoom === -Infinity) {
      zoomBounds.maxNativeZoom = zoomBounds.maxZoom;
    }
    this.zoomBounds = zoomBounds;
  }

  // Resolve the layer's projection: its own <map-meta name="projection">, else a
  // unanimous <map-extent units>, else the parent viewer's projection (warning
  // once when nothing declares one). Ported from MapML.js layer.js; remote
  // (<map-layer src>) content is read from the shadow root.
  getProjection() {
    let mapml = this.src ? this.shadowRoot : this;
    let projection = this.parentElement.projection;
    if (mapml?.querySelector('map-meta[name=projection][content]')) {
      projection =
        Util._metaContentToObject(
          mapml
            .querySelector('map-meta[name=projection]')
            .getAttribute('content')
        ).content || projection;
    } else if (mapml?.querySelector('map-extent[units]')) {
      const getProjectionFrom = (extents) => {
        let extentProj = extents[0].attributes.units.value;
        let isMatch = true;
        for (let i = 0; i < extents.length; i++) {
          if (extentProj !== extents[i].attributes.units.value) {
            isMatch = false;
          }
        }
        return isMatch ? extentProj : null;
      };
      projection =
        getProjectionFrom(
          Array.from(mapml.querySelectorAll('map-extent[units]'))
        ) || projection;
    } else if (mapml) {
      const message = `A projection was not assigned to the '${this.label}' Layer. \nPlease specify a projection for that layer using a map-meta element. \nSee more here - https://maps4html.org/web-map-doc/docs/elements/meta/`;
      if (!this.loggedMessages.has(message)) {
        console.log(message);
        this.loggedMessages.add(message);
      }
    }
    return projection;
  }
}
