/**
 * Parse a `<map-geometry>` element into an OpenLayers geometry.
 *
 * Re-architected from MapML.js's Leaflet SVG feature renderer
 * (`src/mapml/features/path.js` `_convertMarkup`/`_coordinateToArrays`): the
 * same coordinate-text parsing and `Util.pointToPCRSPoint` transform, but the
 * output is an `ol/geom` object in PCRS coordinates instead of Leaflet pixel
 * rings. PCRS === the map view's projected coordinates (e.g. OSMTILE PCRS is
 * EPSG:3857 metres), so the geometry drops straight onto an `ol/source/Vector`.
 *
 * First slice: static inline geometry only. `<map-span>`/`<map-a>` subrings are
 * flattened (their per-coordinate styling/links land with feature interactivity).
 */
import GeometryCollection from 'ol/geom/GeometryCollection.js';
import Point from 'ol/geom/Point.js';
import MultiPoint from 'ol/geom/MultiPoint.js';
import LineString from 'ol/geom/LineString.js';
import MultiLineString from 'ol/geom/MultiLineString.js';
import Polygon from 'ol/geom/Polygon.js';
import MultiPolygon from 'ol/geom/MultiPolygon.js';
import { Util } from '../utils/Util.js';
import { toPoint as point } from '../geometry/Point.js';
import { toBounds as bounds } from '../geometry/Bounds.js';

// Extract a link descriptor from a `<map-a href>` wrapper (== MapML.js
// path.js `_convertWrappers` link branch): { url, target?, type?, inPlace? }.
function extractLink(aEl) {
  const url = aEl.getAttribute('href');
  if (!url) return null;
  const link = { url };
  if (aEl.hasAttribute('target')) link.target = aEl.getAttribute('target');
  if (aEl.hasAttribute('type')) link.type = aEl.getAttribute('type');
  if (aEl.hasAttribute('inplace')) link.inPlace = true;
  return link;
}

// Resolve the element that directly contains the geometry shape(s): either the
// `<map-geometry>` itself or a `<map-a>`/`<map-span>` wrapper nested under it
// (MapML.js finds shapes by descendant query and walks up via
// `_getGeometryParents`; here we descend through the wrappers instead). The
// first `<map-a href>` encountered supplies the feature's link.
function resolveGeometryRoot(geomEl) {
  let root = geomEl;
  let link = null;
  let node = geomEl.firstElementChild;
  while (node && (node.nodeName === 'MAP-A' || node.nodeName === 'MAP-SPAN')) {
    if (!link && node.nodeName === 'MAP-A') {
      link = extractLink(node);
    }
    root = node;
    node = node.firstElementChild;
  }
  return { root, link };
}


// A single <map-coordinates> element's text -> array of PCRS [x, y] pairs.
// Nested <map-span>/<map-a> markup is stripped (textContent + tag strip), as in
// MapML.js path.js `_coordinateToArrays` (`noSpan`/`pairs` regexes).
function coordinatesToPCRS(coordsEl, ctx, allPoints) {
  const noSpan = coordsEl.textContent.replace(/(<([^>]+)>)/gi, '');
  const pairs = noSpan.trim().match(/(\S+\s+\S+)/gim) || [];
  const ring = [];
  for (const p of pairs) {
    const numPair = [];
    p.split(/\s+/gim).forEach(Util._parseNumber, numPair);
    const pt = Util.pointToPCRSPoint(
      point(numPair),
      ctx.zoom,
      ctx.projection,
      ctx.cs
    );
    if (!pt) continue;
    ring.push([pt.x, pt.y]);
    allPoints.push(pt);
  }
  return ring;
}

function shapeToGeom(shapeEl, ctx, allPoints) {
  const coordsEls = shapeEl.querySelectorAll('map-coordinates');
  switch (shapeEl.tagName.toUpperCase()) {
    case 'MAP-POINT': {
      const ring = coordinatesToPCRS(coordsEls[0], ctx, allPoints);
      return ring.length ? new Point(ring[0]) : null;
    }
    case 'MAP-MULTIPOINT': {
      const ring = coordinatesToPCRS(coordsEls[0], ctx, allPoints);
      return ring.length ? new MultiPoint(ring) : null;
    }
    case 'MAP-LINESTRING': {
      const ring = coordinatesToPCRS(coordsEls[0], ctx, allPoints);
      return ring.length ? new LineString(ring) : null;
    }
    case 'MAP-MULTILINESTRING': {
      const lines = [];
      for (const c of coordsEls) {
        const ring = coordinatesToPCRS(c, ctx, allPoints);
        if (ring.length) lines.push(ring);
      }
      return lines.length ? new MultiLineString(lines) : null;
    }
    case 'MAP-POLYGON': {
      // Each <map-coordinates> is a ring: first the outer boundary, then holes.
      const rings = [];
      for (const c of coordsEls) {
        const ring = coordinatesToPCRS(c, ctx, allPoints);
        if (ring.length) rings.push(ring);
      }
      return rings.length ? new Polygon(rings) : null;
    }
    case 'MAP-MULTIPOLYGON': {
      const polys = [];
      for (const poly of shapeEl.querySelectorAll(':scope > map-polygon')) {
        const rings = [];
        for (const c of poly.querySelectorAll('map-coordinates')) {
          const ring = coordinatesToPCRS(c, ctx, allPoints);
          if (ring.length) rings.push(ring);
        }
        if (rings.length) polys.push(rings);
      }
      return polys.length ? new MultiPolygon(polys) : null;
    }
    default:
      return null;
  }
}

const SHAPE_SELECTOR =
  ':scope > map-point, :scope > map-multipoint, :scope > map-linestring,' +
  ' :scope > map-multilinestring, :scope > map-polygon, :scope > map-multipolygon';

/**
 * @param {HTMLElement} geomEl - a `<map-geometry>` element
 * @param {Object} opts - { projection: String, zoom: Number, fallbackCS: String }
 * @returns {{ geometry: import('ol/geom/Geometry.js').default|null, bounds: Object,
 *   link: Object|null }}
 *   `geometry` is in PCRS/view-projection coordinates; `bounds` is a PCRS
 *   Bounds; `link` is a `<map-a>` link descriptor when the geometry is wrapped
 *   in one, else null.
 */
export function parseGeometry(geomEl, { projection, zoom, fallbackCS }) {
  const cs = geomEl.getAttribute('cs') || fallbackCS;
  const ctx = { projection, zoom, cs };
  const allPoints = [];
  let geometry = null;

  // A <map-a>/<map-span> may wrap the geometry; resolve the real container and
  // capture any hyperlink before selecting shapes relative to it.
  const { root, link } = resolveGeometryRoot(geomEl);

  const collection = root.querySelector(':scope > map-geometrycollection');
  if (collection) {
    const geoms = [];
    for (const shapeEl of collection.children) {
      const g = shapeToGeom(shapeEl, ctx, allPoints);
      if (g) geoms.push(g);
    }
    geometry = geoms.length ? new GeometryCollection(geoms) : null;
  } else {
    const shapeEl = root.querySelector(SHAPE_SELECTOR);
    geometry = shapeEl ? shapeToGeom(shapeEl, ctx, allPoints) : null;
  }

  let bnds;
  for (const pt of allPoints) {
    bnds = bnds ? bnds.extend(pt) : bounds(pt, pt);
  }
  return { geometry, bounds: bnds, link };
}
