/**
 * `<map-style>` — inline CSS that styles a layer's features. Ported from
 * MapML.js `src/map-style.js` (`HTMLStyleElement`).
 *
 * The element mirrors its `textContent` into a generated `<style>`
 * (`this.styleElement`) that is rendered — via the owning layer's
 * `renderStyles` — into that layer's shadow-DOM container, alongside the hidden
 * per-feature style probes (see `resolveStyle.js`). A `MutationObserver` keeps
 * the generated `<style>` in sync when the author edits the CSS at runtime.
 *
 * The `media` attribute is not yet honoured: `matchMedia` (map-scoped media
 * queries) lands with the i18n/matchMedia phase, so a media-gated `<map-style>`
 * currently always connects. TODO: register the media query once available.
 */
import { Util } from './mapml/utils/Util.js';

export class HTMLStyleElement extends HTMLElement {
  static get observedAttributes() {
    return ['media'];
  }

  get media() {
    return this.getAttribute('media');
  }
  set media(val) {
    this.setAttribute('media', val);
  }

  getMapEl() {
    return Util.getClosest(this, 'mapml-viewer,map[is=web-map]');
  }

  constructor() {
    super();
  }

  _connect() {
    this.styleElement = document.createElement('style');
    this.styleElement.mapStyle = this;
    this.styleElement.textContent = this.textContent;
    copyAttributes(this, this.styleElement);

    const host = this._stylesheetHost;
    const layer = _renderStylesTarget(host);
    if (layer) {
      layer.renderStyles(this);
      layer._restyleFeatures?.();
    }

    // Keep the generated <style> in sync with author edits to the map-style
    // textContent (ported from MapML.js), then restyle.
    this._observer = new MutationObserver(() => {
      this.styleElement.textContent = this.textContent;
      _renderStylesTarget(this._stylesheetHost)?._restyleFeatures?.();
    });
    this._observer.observe(this, {
      childList: true,
      subtree: true,
      characterData: true
    });

    function copyAttributes(source, target) {
      return Array.from(source.attributes).forEach((attribute) => {
        if (
          attribute.nodeName !== 'media' &&
          attribute.nodeName !== 'data-testid'
        ) {
          target.setAttribute(attribute.nodeName, attribute.nodeValue);
        }
      });
    }
  }

  _disconnect() {
    if (this._observer) {
      this._observer.disconnect();
    }
    if (this.styleElement) {
      this.styleElement.remove();
      delete this.styleElement;
      _renderStylesTarget(this._stylesheetHost)?._restyleFeatures?.();
    }
  }

  async connectedCallback() {
    this._hasConnected = true;
    // If the parent is a shadow root, the host (a <map-layer> or <map-link>) is
    // the styling target; otherwise the light-DOM parent element.
    this._stylesheetHost =
      this.getRootNode() instanceof ShadowRoot
        ? this.getRootNode().host
        : this.parentElement;
    if (!this._stylesheetHost) return;

    // Ensure the owning layer (and its feature/style container) exists before
    // rendering. For a <map-layer> host this needs the viewer to be ready.
    const viewer = this.getMapEl();
    if (viewer) await viewer.whenReady();
    if (!this.isConnected) return;
    this._connect();
  }

  disconnectedCallback() {
    this._disconnect();
  }
}

// Resolve the renderStyles-capable layer object for a styling host element.
// <map-layer> -> its MapFeatureLayer; <map-link rel=features> -> its templated
// feature layer. (<map-extent> feature styling is deferred.)
export function _renderStylesTarget(host) {
  if (!host) return undefined;
  const tag = host.tagName;
  if (tag === 'MAP-LAYER') {
    return host._getFeatureLayer?.();
  }
  if (tag === 'MAP-LINK') {
    return host._getTemplatedFeatureLayer?.();
  }
  return undefined;
}
