/**
 * Map navigation history for `<mapml-viewer>` — the OpenLayers port of the
 * back / forward / reload behaviour that MapML.js implements on its Leaflet
 * viewer (see mapml.js src/mapml-viewer.js `_addToHistory` / `back` /
 * `forward` / `reload`).
 *
 * MapML.js snapshots the map's pixel-bounds centre + zoom on every `moveend`
 * and replays them by `panBy` pixel deltas. OpenLayers exposes the view state
 * directly, so a snapshot is simply the view `center` (in projected units) and
 * `zoom`, replayed with `View.setCenter` / `View.setZoom`. The ring-buffer
 * bookkeeping (index, future-truncation, traversal guard) mirrors MapML.js so
 * the two ports stay diffable.
 */
export class MapHistory {
  constructor(map) {
    this._map = map;
    this._history = [];
    this._historyIndex = -1;
    // Number of upcoming `moveend` events to ignore because they were caused by
    // our own back/forward/reload replay rather than by the user.
    this._traversalCall = 0;
    this._onMoveEnd = this._addToHistory.bind(this);
  }

  enable() {
    if (this._enabled) {
      return this;
    }
    this._enabled = true;
    this._map.on('moveend', this._onMoveEnd);
    this.reset();
    return this;
  }

  disable() {
    if (!this._enabled) {
      return this;
    }
    this._enabled = false;
    this._map.un('moveend', this._onMoveEnd);
    return this;
  }

  reset() {
    this._history = [];
    this._historyIndex = -1;
    this._traversalCall = 0;
    this._addToHistory();
  }

  _snapshot() {
    const view = this._map.getView();
    return { center: view.getCenter(), zoom: view.getZoom() };
  }

  _addToHistory() {
    if (this._traversalCall > 0) {
      this._traversalCall--;
      return;
    }
    const location = this._snapshot();
    // OpenLayers can emit a `moveend` right after the first render that
    // reports the same view as the initial reset() snapshot; skip such
    // no-op moves so they don't spuriously enable Back/Reload.
    const current = this._history[this._historyIndex];
    if (current && this._sameLocation(current, location)) {
      return;
    }
    this._historyIndex++;
    this._history.splice(this._historyIndex, 0, location);
    // Panning/zooming while inside the history truncates the future.
    if (this._historyIndex + 1 !== this._history.length) {
      this._history.length = this._historyIndex + 1;
    }
    this._notify();
  }

  _sameLocation(a, b) {
    return (
      a.zoom === b.zoom &&
      a.center?.[0] === b.center?.[0] &&
      a.center?.[1] === b.center?.[1]
    );
  }

  back() {
    if (this._historyIndex > 0) {
      this._historyIndex--;
      this._traversalCall = 1;
      this._applyLocation(this._history[this._historyIndex]);
      this._notify();
    }
  }

  forward() {
    if (this._historyIndex < this._history.length - 1) {
      this._historyIndex++;
      this._traversalCall = 1;
      this._applyLocation(this._history[this._historyIndex]);
      this._notify();
    }
  }

  reload() {
    if (this._history.length === 0) {
      return;
    }
    const initialLocation = this._history[0];
    this._history = [initialLocation];
    this._historyIndex = 0;
    this._traversalCall = 1;
    this._applyLocation(initialLocation);
    this._notify();
  }

  _applyLocation(location) {
    const view = this._map.getView();
    view.setCenter(location.center);
    if (location.zoom !== undefined) {
      view.setZoom(location.zoom);
    }
  }

  // Which of the three history actions are currently meaningful. The context
  // menu queries this when it opens to enable/disable Back/Forward/Reload.
  getState() {
    return {
      canBack: this._historyIndex > 0,
      canForward: this._historyIndex < this._history.length - 1,
      canReload: this._historyIndex > 0
    };
  }

  _notify() {
    if (typeof this.onChange === 'function') {
      this.onChange(this.getState());
    }
  }
}
