/**
 * `<map-link>` — Phase 1 supports `rel="tile" type="image/*"` inside a
 * `<map-extent>`. Named `HTMLLinkElement` to match MapML.js (module-scoped,
 * deliberately shadowing the built-in interface).
 *
 * It rewrites the author's `tref` variable names to OpenLayers `{x}/{y}/{z}`
 * tokens (using the sibling `<map-input>` axis/type metadata) and adds an
 * `ol/layer/Tile` backed by the projection + tile grid derived from the
 * `M[projection]` tables. Other `rel` values are recognised but no-ops.
 */
/* global M */
import TileLayer from 'ol/layer/Tile.js';
import ImageLayer from 'ol/layer/Image.js';
import XYZ from 'ol/source/XYZ.js';
import ImageSource from 'ol/source/Image.js';
import { decode } from 'ol/Image.js';
import { getHeight, getWidth } from 'ol/extent.js';

import { getProjection, getTileGrid } from './mapml/geo/crs/olcrs.js';
import { Util } from './mapml/utils/Util.js';
import { TemplatedFeaturesOrTilesLayer } from './mapml/layers/TemplatedFeaturesOrTilesLayer.js';
import { _renderStylesTarget } from './map-style.js';
import { nextControlId } from './mapml/elementSupport/layers/layerControlUtils.js';
import { toBounds as bounds } from './mapml/geometry/Bounds.js';
import { toPoint as point } from './mapml/geometry/Point.js';

const RASTER_IMAGE_TYPES = /^image\/(png|jpeg|jpg|webp|gif|avif|\*)$/i;

export class HTMLLinkElement extends HTMLElement {
  static get observedAttributes() {
    return ['rel', 'tref', 'type'];
  }

  get rel() {
    return (this.getAttribute('rel') || '').toLowerCase();
  }
  get tref() {
    return this.getAttribute('tref') || '';
  }
  get type() {
    return this.getAttribute('type') || 'image/*';
  }
  get href() {
    if (this.hasAttribute('href')) {
      return new URL(this.getAttribute('href'), this.getBase()).href;
    }
    return undefined;
  }
  get disabled() {
    return this.hasAttribute('disabled');
  }

  getMapEl() {
    return Util.getClosest(this, 'mapml-viewer,map[is=web-map]');
  }
  getLayerEl() {
    return Util.getClosest(this, 'map-layer,layer-');
  }
  // Resolve the base URL for the link's href/tref. For grafted (remote) links
  // the base is the owning <map-layer src>; otherwise the document baseURI.
  // Ported (simplified) from MapML.js map-link.js `getBase`.
  getBase() {
    const root = this.getRootNode();
    if (root instanceof ShadowRoot) {
      const layer = root.host;
      return new URL(layer.src, layer.baseURI).href;
    }
    return this.baseURI;
  }

  connectedCallback() {
    this._viewer = Util.getClosest(this, 'mapml-viewer');
    this._extent = this.closest('map-extent');
    if (this._extent) {
      this._initTemplateVars();
      if (this.rel === 'query' && this._templateVars) {
        // A query link renders no persistent layer; it is consulted by the
        // map-level QueryHandler on click. Extend its template vars with the
        // role -> input-name map and give it a shadow root to hold the queried
        // <map-feature>s (mirrors MapML.js map-link.js `_processTemplate`).
        Object.assign(this._templateVars, this._setupQueryVars(this._templateVars));
        this._templateVars.linkEl = this;
        if (!this.shadowRoot) {
          this.attachShadow({ mode: 'open' });
        }
      }
    }
    void this._apply();
  }

  disconnectedCallback() {
    if (this._featuresLayer) {
      this._featuresLayer.destroy();
      this._featuresLayer = null;
      this._layerRegistry = null;
    }
    if (this.link) {
      this.link.remove();
      delete this.link;
      _renderStylesTarget(this._stylesheetHost)?._restyleFeatures?.();
    }
    if (this._layer && this._targetCollection) {
      this._targetCollection.remove(this._layer);
    }
    this._layer = null;
    this._targetCollection = null;
  }

  // Tear down this link's renderer artefact and re-apply it, so a changed
  // template variable (e.g. a sibling <map-select> value) takes effect. OL
  // analog of MapML.js map-select redrawing the extent's `_extentLayer`.
  refresh() {
    if (this._featuresLayer) {
      this._featuresLayer.destroy();
      this._featuresLayer = null;
      this._layerRegistry = null;
    }
    if (this._layer && this._targetCollection) {
      this._targetCollection.remove(this._layer);
    }
    this._layer = null;
    this._targetCollection = null;
    return this._apply();
  }

  _apply() {
    if (this.rel === 'tile') {
      return this._applyTile();
    }
    if (this.rel === 'image') {
      return this._applyImage();
    }
    if (this.rel === 'features') {
      return this._applyFeatures();
    }
    if (this.rel === 'stylesheet') {
      return this._applyStylesheet();
    }
    if (
      this.rel === 'style' ||
      this.rel === 'self' ||
      this.rel === 'self style' ||
      this.rel === 'style self'
    ) {
      return this._createSelfOrStyleLink();
    }
  }

  // `rel="style" | "self style" | "style self"` — a named alternate style of
  // the owning layer, surfaced as a radio option in the layer control. Clicking
  // it dispatches `changestyle` on the <map-layer>, which swaps its `src` to the
  // alternate document. Ported from MapML.js map-link.js `_createSelfOrStyleLink`.
  _createSelfOrStyleLink() {
    const layerEl = this.getLayerEl();
    if (!layerEl) return;
    const changeStyle = (e) => {
      e.preventDefault();
      e.stopPropagation();
      layerEl.dispatchEvent(
        new CustomEvent('changestyle', {
          detail: { src: e.target.getAttribute('data-href') }
        })
      );
    };

    const styleOption = document.createElement('div');
    const styleOptionInput = styleOption.appendChild(
      document.createElement('input')
    );
    styleOptionInput.setAttribute('type', 'radio');
    styleOptionInput.setAttribute('id', 'rad-' + nextControlId());
    // All style radios of one layer share a name so they form a single group.
    // (MapML.js stamps each option div separately, which does not group them;
    // grouping per layer matches the intended single-selection behaviour.)
    layerEl._styleGroupName =
      layerEl._styleGroupName || 'styles-' + nextControlId();
    styleOptionInput.setAttribute('name', layerEl._styleGroupName);
    styleOptionInput.setAttribute('value', this.getAttribute('title'));
    styleOptionInput.setAttribute('data-href', this.href);
    const styleOptionLabel = styleOption.appendChild(
      document.createElement('label')
    );
    styleOptionLabel.setAttribute('for', styleOptionInput.getAttribute('id'));
    styleOptionLabel.innerText = this.title;
    if (this.rel === 'style self' || this.rel === 'self style') {
      styleOptionInput.checked = true;
    }
    this._styleOption = styleOption;
    styleOptionInput.addEventListener('click', changeStyle);
  }

  getLayerControlOption() {
    return this._styleOption;
  }

  // `rel="stylesheet"` — import an author CSS stylesheet that styles the owning
  // layer's features. Ported from MapML.js map-link.js `_createStylesheetLink`
  // (non-pmtiles branch). The generated <link> is rendered into the owning
  // layer's shadow-DOM style container; feature styles resolve through it.
  async _applyStylesheet() {
    if (this.disabled || !this.hasAttribute('href')) return;
    const viewer = this.getMapEl();
    if (viewer) await viewer.whenReady();
    if (!this.isConnected) return;
    this._createStylesheetLink();
  }

  _createStylesheetLink() {
    this._stylesheetHost =
      this.getRootNode() instanceof ShadowRoot
        ? this.getRootNode().host
        : this.parentElement;
    if (!this._stylesheetHost) return;

    this.link = document.createElement('link');
    this.link.mapLink = this;
    this.link.setAttribute('rel', 'stylesheet');
    this.link.setAttribute('href', this.href);
    copyAttributes(this, this.link);

    const layer = _renderStylesTarget(this._stylesheetHost);
    if (layer) layer.renderStyles(this);
    // The <link> CSS loads asynchronously; re-resolve feature styles once it
    // has (getComputedStyle only reflects the rules after load).
    this.link.addEventListener('load', () => {
      _renderStylesTarget(this._stylesheetHost)?._restyleFeatures?.();
    });

    function copyAttributes(source, target) {
      return Array.from(source.attributes).forEach((attribute) => {
        if (attribute.nodeName !== 'href' && attribute.nodeName !== 'media')
          target.setAttribute(attribute.nodeName, attribute.nodeValue);
      });
    }
  }

  async _applyTile() {
    if (!RASTER_IMAGE_TYPES.test(this.type)) {
      console.warn(
        `<map-link rel="tile">: unsupported type ${JSON.stringify(this.type)}.`
      );
      return;
    }
    if (!this.tref || !this._extent || !this._viewer) {
      return;
    }

    const viewer = this._viewer;
    await viewer.whenReady();
    if (!this.isConnected) {
      return;
    }

    const mProj = window.M[viewer.projection];
    // DOM-order z-index among the renderable links in this extent, matching
    // MapML.js: Array.from(parentExtent.querySelectorAll(...)).indexOf(this).
    this.zIndex = Array.from(
      this._extent.querySelectorAll(
        'map-link[rel=image],map-link[rel=tile],map-link[rel=features]'
      )
    ).indexOf(this);
    const source = new XYZ({
      projection: getProjection(mProj),
      tileGrid: getTileGrid(mProj),
      url: this._toOLTemplate(this.tref, this._extent.getInputs()),
      attributions: this._attribution()
    });
    const layerOptions = { source };
    // Constrain display zoom + geographic extent from the extent's derived
    // bounds, mirroring MapML.js's TemplatedTileLayer (zoomBounds -> GridLayer
    // min/maxZoom; extentBounds -> visibility). OL's layer minZoom is
    // exclusive, so subtract 1 to keep the inclusive MapML minZoom visible.
    if (this._templateVars) {
      const zoomBounds = this.getZoomBounds();
      const extentBounds = this.getBounds();
      layerOptions.minZoom = zoomBounds.minZoom - 1;
      layerOptions.maxZoom = zoomBounds.maxZoom;
      layerOptions.extent = [
        extentBounds.min.x,
        extentBounds.min.y,
        extentBounds.max.x,
        extentBounds.max.y
      ];
    }
    this._layer = new TileLayer(layerOptions);
    // Render order is driven by zIndex, mirroring MapML.js's `zIndex: this.zIndex`.
    this._layer.setZIndex(this.zIndex);
    // Nest inside the extent's ol/layer/Group (in DOM order), not the map root.
    this._targetCollection = this._extent.getLayerGroup().getLayers();
    this._targetCollection.push(this._layer);
  }

  // `rel="image"` — a templated single image (WMS GetMap-style). Ported from
  // MapML.js TemplatedImageLayer: a fresh image covering the current view is
  // requested on every view change, its bounds/size substituted into `tref`.
  // In OL this maps onto an ol/source/Image `loader`, whose requested extent is
  // the view extent (in PCRS metres, = the view projection) and resolution is
  // the map resolution, so width/height derive to the map's CSS-pixel size.
  async _applyImage() {
    if (!this.tref || !this._extent || !this._viewer) {
      return;
    }

    const viewer = this._viewer;
    await viewer.whenReady();
    if (!this.isConnected) {
      return;
    }

    const mProj = window.M[viewer.projection];
    // DOM-order z-index among the renderable links in this extent, matching
    // MapML.js: Array.from(parentExtent.querySelectorAll(...)).indexOf(this).
    this.zIndex = Array.from(
      this._extent.querySelectorAll(
        'map-link[rel=image],map-link[rel=tile],map-link[rel=features]'
      )
    ).indexOf(this);

    // Map author input names to width/height/left/right/top/bottom (+ hidden)
    // roles the template expects (MapML.js `_setUpExtentTemplateVars`).
    const extentVars = this._setUpExtentTemplateVars(this._templateVars);
    const source = new ImageSource({
      projection: getProjection(mProj),
      attributions: this._attribution(),
      loader: (extent, resolution) => {
        const url = this._imageUrl(extentVars, extent, resolution);
        const image = new Image();
        return decode(image, url).then((img) => {
          const resX = getWidth(extent) / img.width;
          const resY = getHeight(extent) / img.height;
          return {
            image: img,
            extent,
            resolution: resX !== resY ? [resX, resY] : resY,
            pixelRatio: 1
          };
        });
      }
    });
    const layerOptions = { source };
    // Constrain display zoom + geographic extent from the extent's derived
    // bounds, mirroring the tile branch (see _applyTile).
    if (this._templateVars) {
      const zoomBounds = this.getZoomBounds();
      const extentBounds = this.getBounds();
      layerOptions.minZoom = zoomBounds.minZoom - 1;
      layerOptions.maxZoom = zoomBounds.maxZoom;
      layerOptions.extent = [
        extentBounds.min.x,
        extentBounds.min.y,
        extentBounds.max.x,
        extentBounds.max.y
      ];
    }
    this._layer = new ImageLayer(layerOptions);
    this._layer.setZIndex(this.zIndex);
    this._targetCollection = this._extent.getLayerGroup().getLayers();
    this._targetCollection.push(this._layer);
  }

  // `rel="features"` — a templated vector-feature layer. Ported from MapML.js
  // TemplatedFeaturesOrTilesLayer: on the initial add and every view change a
  // fresh MapML document covering the current view is fetched, its
  // `<map-feature>`s (and, once ported, `<map-tile>`s) grafted into this link's
  // shadow root and rendered. The fetch/graft cycle lives in the
  // `TemplatedFeaturesOrTilesLayer` controller; the vector layer it owns is
  // nested in the extent's group like tile/image.
  async _applyFeatures() {
    if (!this.tref || !this._extent || !this._viewer || !this._templateVars) {
      return;
    }

    const viewer = this._viewer;
    await viewer.whenReady();
    if (!this.isConnected) {
      return;
    }

    // map-feature retrieved by this link is stored in a shadow root it owns.
    if (!this.shadowRoot) {
      this.attachShadow({ mode: 'open' });
    }
    // DOM-order z-index among the renderable links in this extent, matching
    // MapML.js: Array.from(parentExtent.querySelectorAll(...)).indexOf(this).
    this.zIndex = Array.from(
      this._extent.querySelectorAll(
        'map-link[rel=image],map-link[rel=tile],map-link[rel=features]'
      )
    ).indexOf(this);
    // Adjacent grafted <map-feature>/<map-tile> runs each become one
    // position-keyed sub-layer (MapFeatureLayer/MapTileLayer) via this registry,
    // so interleaved responses keep DOM z-order. == MapML.js link._layerRegistry.
    this._layerRegistry = new Map();
    this._featuresLayer = new TemplatedFeaturesOrTilesLayer(
      this,
      this._templateVars,
      {
        viewer,
        projection: viewer.projection,
        zoomBounds: this.getZoomBounds(),
        extentBounds: this.getBounds(),
        zIndex: this.zIndex
      }
    );
    this._layer = this._featuresLayer.getLayer();
    this._targetCollection = this._extent.getLayerGroup().getLayers();
    this._targetCollection.push(this._layer);
  }

  // The TemplatedFeaturesOrTilesLayer controller for a rel=features link. It
  // owns the position-keyed sub-layer group (into which grafted
  // <map-feature>/<map-tile> runs render themselves) and fans author styles out
  // to its feature sub-layers, so it is also the renderStyles target for a
  // grafted <map-style>/<map-link rel=stylesheet>.
  _getTemplatedFeatureLayer() {
    return this._featuresLayer ?? null;
  }

  // Substitute the extent template variables for the given view `extent` (PCRS
  // metres [minX,minY,maxX,maxY]) + `resolution`, mirroring MapML.js
  // TemplatedImageLayer.getImageUrl. width/height are the request size in CSS
  // pixels; left/right/top/bottom are the PCRS bounds; other (hidden/select)
  // variables are resolved by name (functions are called, as Leaflet's
  // template does).
  _imageUrl(extentVars, extent, resolution) {
    const [minX, minY, maxX, maxY] = extent;
    const ev = extentVars.extent;
    const obj = {};
    obj[ev.width] = Math.round((maxX - minX) / resolution);
    obj[ev.height] = Math.round((maxY - minY) / resolution);
    obj[ev.left] = minX;
    obj[ev.right] = maxX;
    obj[ev.top] = maxY;
    obj[ev.bottom] = minY;
    for (const v in ev) {
      if (['width', 'height', 'left', 'right', 'top', 'bottom'].indexOf(v) < 0) {
        obj[v] = typeof ev[v] === 'function' ? ev[v]() : ev[v];
      }
    }
    return this.tref.replace(/{(.*?)}/g, (match, name) =>
      obj[name] !== undefined ? obj[name] : match
    );
  }

  // Port of MapML.js TemplatedImageLayer `_setUpExtentTemplateVars`: build an
  // { extent: { width, height, left, right, top, bottom, ...hidden } } map from
  // the inputs associated to this link, keyed role -> author input NAME.
  _setUpExtentTemplateVars(template) {
    const extentVarNames = { extent: {} },
      inputs = template.values;

    for (let i = 0; i < template.values.length; i++) {
      const type = inputs[i].getAttribute('type'),
        units = inputs[i].getAttribute('units'),
        axis = inputs[i].getAttribute('axis'),
        name = inputs[i].getAttribute('name'),
        position = inputs[i].getAttribute('position'),
        select = inputs[i].tagName.toLowerCase() === 'map-select';
      if (type === 'width') {
        extentVarNames.extent.width = name;
      } else if (type === 'height') {
        extentVarNames.extent.height = name;
      } else if (
        type === 'location' &&
        (units === 'pcrs' || units === 'gcrs')
      ) {
        switch (axis) {
          case 'longitude':
          case 'easting':
            if (position) {
              if (position.match(/.*?-left/i)) {
                extentVarNames.extent.left = name;
              } else if (position.match(/.*?-right/i)) {
                extentVarNames.extent.right = name;
              }
            }
            break;
          case 'latitude':
          case 'northing':
            if (position) {
              if (position.match(/top-.*?/i)) {
                extentVarNames.extent.top = name;
              } else if (position.match(/bottom-.*?/i)) {
                extentVarNames.extent.bottom = name;
              }
            }
            break;
        }
      } else if (select) {
        const parsedselect = inputs[i];
        extentVarNames.extent[name] = function () {
          return parsedselect.htmlselect?.value;
        };
      } else {
        const input = inputs[i];
        extentVarNames.extent[name] = function () {
          return input.getAttribute('value');
        };
      }
    }
    return extentVarNames;
  }

  // Rewrite author tref variables to OL {x}/{y}/{z} using the input metadata.
  _toOLTemplate(tref, inputs) {
    let url = tref;
    for (const input of inputs) {
      const token = `{${input.name}}`;
      if (input.type === 'zoom') {
        url = url.replaceAll(token, '{z}');
      } else if (input.axis === 'column') {
        url = url.replaceAll(token, '{x}');
      } else if (input.axis === 'row') {
        url = url.replaceAll(token, '{y}');
      }
    }
    return url;
  }

  // Build attribution HTML from the owning layer's `<map-link rel="license">`
  // children. MapML conveys attribution through license links (per the
  // `<map-link>` spec) rather than an `attribution=` attribute. Multiple
  // license links are joined with `; `.
  _attribution() {
    const layer = Util.getClosest(this, 'map-layer');
    if (!layer) {
      return undefined;
    }
    const parts = [];
    for (const child of (layer.src ? layer.shadowRoot : layer).children) {
      if (child.tagName.toLowerCase() !== 'map-link') {
        continue;
      }
      if ((child.getAttribute('rel') || '').toLowerCase() !== 'license') {
        continue;
      }
      const title = child.getAttribute('title') || '';
      const href = child.getAttribute('href') || '';
      if (!title && !href) {
        continue;
      }
      parts.push(formatLicenseLink(title, href));
    }
    return parts.length > 0 ? parts.join('; ') : undefined;
  }

  // Scoped port of MapML.js map-link.js _initTemplateVars: associates the
  // <map-input>/<map-select> variables referenced by tref (plus the extent's
  // zoom input) to this link. The full URL/template/step/inputsReady fields are
  // built separately by _toOLTemplate, so only the bounds-relevant fields
  // (values, zoom, projection) are populated here.
  _initTemplateVars() {
    var varNamesRe = new RegExp('(?:{)(.*?)(?:})', 'g'),
      zoomInput = this.parentElement.querySelector('map-input[type="zoom" i]'),
      includesZoom = false,
      linkedZoomInput;

    var template = this.tref;
    this.zoomInput = zoomInput;

    var v,
      vcount = template.match(varNamesRe) || [],
      inputs = [];
    while ((v = varNamesRe.exec(template)) !== null) {
      let varName = v[1],
        inp = this.parentElement.querySelector(
          'map-input[name=' + varName + '],map-select[name=' + varName + ']'
        );
      if (inp) {
        inputs.push(inp);
        if (
          inp.hasAttribute('type') &&
          inp.getAttribute('type').toLowerCase() === 'zoom'
        ) {
          linkedZoomInput = inp;
          includesZoom = true;
        }
      }
    }
    if (template && vcount.length === inputs.length) {
      if (!includesZoom && zoomInput) {
        inputs.push(zoomInput);
        linkedZoomInput = zoomInput;
      }
      this._templateVars = {
        template: template,
        values: inputs,
        zoom: linkedZoomInput,
        projection: this.parentElement.units
      };
    }
  }

  // Port of MapML.js map-link.js `_setupQueryVars`: from the inputs associated
  // to this query template, build a `query` object mapping each query ROLE
  // (width, height, x/y/column/row, mapleft/…, tilei/…, zoom, hidden/select
  // value functions) to the author's input NAME, so QueryHandler can compute
  // the substitution values keyed by input name.
  _setupQueryVars(template) {
    var queryVarNames = { query: {} },
      inputs = template.values;

    for (var i = 0; i < template.values.length; i++) {
      var type = inputs[i].getAttribute('type'),
        units = inputs[i].getAttribute('units'),
        axis = inputs[i].getAttribute('axis'),
        name = inputs[i].getAttribute('name'),
        position = inputs[i].getAttribute('position'),
        rel = inputs[i].getAttribute('rel'),
        select = inputs[i].tagName.toLowerCase() === 'map-select';
      if (type === 'width') {
        queryVarNames.query.width = name;
      } else if (type === 'height') {
        queryVarNames.query.height = name;
      } else if (type === 'location') {
        switch (axis) {
          case 'x':
          case 'y':
          case 'column':
          case 'row':
            queryVarNames.query[axis] = name;
            break;
          case 'longitude':
          case 'easting':
            if (position) {
              if (position.match(/.*?-left/i)) {
                if (rel === 'pixel') {
                  queryVarNames.query.pixelleft = name;
                } else if (rel === 'tile') {
                  queryVarNames.query.tileleft = name;
                } else {
                  queryVarNames.query.mapleft = name;
                }
              } else if (position.match(/.*?-right/i)) {
                if (rel === 'pixel') {
                  queryVarNames.query.pixelright = name;
                } else if (rel === 'tile') {
                  queryVarNames.query.tileright = name;
                } else {
                  queryVarNames.query.mapright = name;
                }
              }
            } else {
              queryVarNames.query[axis] = name;
            }
            break;
          case 'latitude':
          case 'northing':
            if (position) {
              if (position.match(/top-.*?/i)) {
                if (rel === 'pixel') {
                  queryVarNames.query.pixeltop = name;
                } else if (rel === 'tile') {
                  queryVarNames.query.tiletop = name;
                } else {
                  queryVarNames.query.maptop = name;
                }
              } else if (position.match(/bottom-.*?/i)) {
                if (rel === 'pixel') {
                  queryVarNames.query.pixelbottom = name;
                } else if (rel === 'tile') {
                  queryVarNames.query.tilebottom = name;
                } else {
                  queryVarNames.query.mapbottom = name;
                }
              }
            } else {
              queryVarNames.query[axis] = name;
            }
            break;
          case 'i':
            if (units === 'tile') {
              queryVarNames.query.tilei = name;
            } else {
              queryVarNames.query.mapi = name;
            }
            break;
          case 'j':
            if (units === 'tile') {
              queryVarNames.query.tilej = name;
            } else {
              queryVarNames.query.mapj = name;
            }
            break;
          default:
          // unsupported axis value
        }
      } else if (type === 'zoom') {
        queryVarNames.query.zoom = name;
      } else if (select) {
        const parsedselect = inputs[i];
        queryVarNames.query[name] = function () {
          return parsedselect.htmlselect?.value;
        };
      } else {
        const input = inputs[i];
        queryVarNames.query[name] = function () {
          return input.getAttribute('value');
        };
      }
    }
    return queryVarNames;
  }

  getZoomBounds() {
    return this._getZoomBounds(this._templateVars.zoom);
  }

  getBounds() {
    let template = this._templateVars;
    let inputs = template.values,
      projection = this.parentElement.units,
      boundsUnit = {};
    boundsUnit.name = M.FALLBACK_CS;
    let bnds = M[projection].options.crs.tilematrix.bounds(0),
      locInputs = false;
    for (let i = 0; i < inputs.length; i++) {
      if (inputs[i].getAttribute('type') === 'location') {
        if (!inputs[i].getAttribute('max') || !inputs[i].getAttribute('min'))
          continue;
        let max = +inputs[i].getAttribute('max'),
          min = +inputs[i].getAttribute('min');
        switch (inputs[i].getAttribute('axis').toLowerCase()) {
          case 'x':
          case 'longitude':
          case 'column':
          case 'easting':
            boundsUnit.name = Util.axisToCS(
              inputs[i].getAttribute('axis').toLowerCase()
            );
            bnds.min.x = min;
            bnds.max.x = max;
            boundsUnit.horizontalAxis = inputs[i]
              .getAttribute('axis')
              .toLowerCase();
            break;
          case 'y':
          case 'latitude':
          case 'row':
          case 'northing':
            boundsUnit.name = Util.axisToCS(
              inputs[i].getAttribute('axis').toLowerCase()
            );
            bnds.min.y = min;
            bnds.max.y = max;
            boundsUnit.verticalAxis = inputs[i]
              .getAttribute('axis')
              .toLowerCase();
            break;
          default:
            break;
        }
      }
    }
    if (
      boundsUnit.horizontalAxis &&
      boundsUnit.verticalAxis &&
      ((boundsUnit.horizontalAxis === 'x' && boundsUnit.verticalAxis === 'y') ||
        (boundsUnit.horizontalAxis === 'longitude' &&
          boundsUnit.verticalAxis === 'latitude') ||
        (boundsUnit.horizontalAxis === 'column' &&
          boundsUnit.verticalAxis === 'row') ||
        (boundsUnit.horizontalAxis === 'easting' &&
          boundsUnit.verticalAxis === 'northing'))
    ) {
      locInputs = true;
    }
    if (locInputs) {
      let zoomValue = this._templateVars.zoom?.hasAttribute('value')
        ? +this._templateVars.zoom.getAttribute('value')
        : 0;
      bnds = Util.boundsToPCRSBounds(
        bnds,
        zoomValue,
        projection,
        boundsUnit.name
      );
    } else if (!locInputs) {
      bnds = this.getFallbackBounds(projection);
    }
    return bnds;
  }
  getFallbackBounds(projection) {
    let bnds;

    let zoom = 0;
    let metaExtent = this.parentElement.getMeta('extent');
    if (metaExtent) {
      let content = Util._metaContentToObject(
          metaExtent.getAttribute('content')
        ),
        cs;

      zoom = content.zoom || zoom;

      let metaKeys = Object.keys(content);
      for (let i = 0; i < metaKeys.length; i++) {
        if (!metaKeys[i].includes('zoom')) {
          cs = Util.axisToCS(metaKeys[i].split('-')[2]);
          break;
        }
      }
      let axes = Util.csToAxes(cs);
      bnds = Util.boundsToPCRSBounds(
        bounds(
          point(
            +content[`top-left-${axes[0]}`],
            +content[`top-left-${axes[1]}`]
          ),
          point(
            +content[`bottom-right-${axes[0]}`],
            +content[`bottom-right-${axes[1]}`]
          )
        ),
        zoom,
        projection,
        cs
      );
    } else {
      let crs = M[projection];
      bnds = crs.options.crs.pcrs.bounds;
    }
    return bnds;
  }
  /**
   * Return BOTH min/max(Display)Zoom AND min/maxNativeZoom which
   * are options that can be passed to GridLayer...
   * https://leafletjs.com/reference.html#gridlayer-minzoom
   *
   * @param {Object} zoomInput - is an element reference to a map-input[type=zoom]
   * @returns {Object} - returns {minZoom: n,maxZoom: n,minNativeZoom: n,maxNativeZoom: n}
   */
  _getZoomBounds(zoomInput) {
    // native variables should ONLY come from map-input min/max attributes
    // BUT they should fall back to map-meta or projection values for min/max (display) zoom
    // display zoom variables should be EQUAL to native unless specified differently
    // via map-meta name=zoom
    // in particular minNativeZoom being > minZoom can be problematic because
    // you fetch tiles at larger scales (i.e. many many small tiles) and render
    // them at smaller scale (i.e. little postage stamps), which can freez your
    // browser and bury a tile cache in requests, getting you banned/blocked
    //
    // minZoom = map-meta name=zoom min || input type=zoom min || projection minZoom
    // minNativeZoom = input type=zoom min || minZoom
    // maxZoom = map-meta name=zoom max || input type=zoom max || projection maxZoom
    // maxNativeZoom = input type=zoom max || maxZoom

    let zoomBounds = {};
    // search document from here up, using closest source of zoom bounds info
    let meta = this.parentElement.getMeta('zoom');
    let metaMin = meta
      ? +Util._metaContentToObject(meta.getAttribute('content'))?.min
      : null;
    zoomBounds.minZoom =
      metaMin || (zoomInput ? +zoomInput.getAttribute('min') : 0);
    zoomBounds.minNativeZoom = zoomInput
      ? +zoomInput.getAttribute('min')
      : zoomBounds.minZoom;
    let metaMax = meta
      ? +Util._metaContentToObject(meta.getAttribute('content'))?.max
      : null;
    zoomBounds.maxZoom =
      metaMax ||
      (zoomInput
        ? +zoomInput.getAttribute('max')
        : M[this.parentElement.units].options.resolutions.length - 1);
    zoomBounds.maxNativeZoom = zoomInput
      ? +zoomInput.getAttribute('max')
      : zoomBounds.maxZoom;

    return zoomBounds;
  }
}

function formatLicenseLink(title, href) {
  const text = escapeHtml(title || href);
  if (!href) {
    return text;
  }
  return `<a href="${escapeHtml(href)}" target="_blank" rel="noopener">${text}</a>`;
}

function escapeHtml(s) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
