/**
 * Stylesheet for the {@link SearchButton} top-left, opt-in control. Ported from
 * MapML.js's `.mapml-search-*` block (`src/mapml.css`), with three deliberate
 * adaptations for this port:
 *
 *   1. Button sized 40×40 (not upstream's 44×44) and framed like the rest of
 *      the OL control set (zoom/reload/fullscreen) so it stacks flush; placed
 *      below the fullscreen button in the top-left column.
 *   2. Focus outlines use the shared `--mapml-focus-ring-color` (owned by the
 *      viewer shadow root) instead of upstream's hard-coded `#4A90D9`, so every
 *      focusable in the map shares one focus colour.
 *   3. Responsive close affordance (DE-3). Upstream fixes the panel at 250px
 *      and hangs the close ledge 24px off its right edge (`right:-24px`). When
 *      the *map* is narrower than the panel + ledge — e.g. a non-full-width map
 *      on a phone — that ledge is clipped off-screen and the panel can only be
 *      dismissed by reloading. Here the panel width is
 *      `min(250px, calc(100% - 26px))`, reserving 26px of map width for the
 *      ledge so it is always on-screen. On maps ≥ 276px wide this resolves to
 *      the exact upstream 250px layout; narrower maps shrink the panel just
 *      enough to keep the close button reachable. `100%` resolves against the
 *      map container, so this reacts to the map's own width (like the
 *      `mapmlviewer` container query), not the viewport's.
 */
export const searchControlCss = /* css */ `
/* Search control. Vertical position (top) is assigned by the viewer's
   _layoutTopLeftColumn so it stacks between zoom and reload regardless of which
   top-left controls are excluded; only the left offset + frame live here. */
.mapml-search-control {
  left: .5em;
  padding: 0;
  background-color: #fff;
  border: 1px solid #e3e3e3;
  border-radius: 4px;
  box-shadow: rgb(0 0 0 / 30%) 0px 1px 4px -1px;
  z-index: 1000;
}
.mapml-search-control button.mapml-search-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin: 0;
  padding: 0;
  cursor: pointer;
  background: #fff;
  border: none;
  border-radius: 4px;
  color: #333;
}
.mapml-search-control button.mapml-search-button svg {
  display: block;
}
.mapml-search-control button.mapml-search-button:hover {
  background: #f4f4f4;
}
.mapml-search-control button.mapml-search-button[aria-disabled='true'] {
  cursor: default;
  color: #bbb;
}
.mapml-search-control button.mapml-search-button[aria-disabled='true']:hover {
  background: #fff;
}
.mapml-search-control > button:hover,
.mapml-search-control > button:focus:not(:focus-visible) {
  outline: none;
}
.mapml-search-control > button:focus-visible {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: 1px;
}

.mapml-search-panel[hidden] {
  display: none !important;
}
.mapml-search-panel {
  position: absolute;
  top: 0;
  left: 0;
  /* DE-3: reserve 26px for the close ledge so it never clips off a narrow map. */
  width: min(250px, calc(100% - 26px));
  height: 100%;
  background: #fff;
  box-shadow: 2px 0 5px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
  transform: translateX(-100%);
  transition: transform 0.2s ease-in-out;
  z-index: 10000;
}
.mapml-search-panel-open {
  transform: translateX(0);
}
.mapml-search-input {
  width: calc(100% - 16px);
  margin: 8px;
  padding: 6px 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
  font-size: 14px;
  box-sizing: border-box;
}
.mapml-search-input:focus {
  outline: 2px solid var(--mapml-focus-ring-color);
  border-color: var(--mapml-focus-ring-color);
}
.mapml-search-results {
  flex: 1;
  overflow-y: auto;
  padding: 0 8px 8px;
}
.mapml-search-result {
  display: block;
  width: 100%;
  padding: 8px;
  border: none;
  border-bottom: 1px solid #eee;
  background: #fff;
  text-align: left;
  font-size: 13px;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mapml-search-result:hover {
  background: #f0f0f0;
}
.mapml-search-result:focus {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: -2px;
}
.mapml-search-panel button.mapml-search-close {
  position: absolute;
  right: -24px;
  top: 50%;
  transform: translateY(-50%);
  width: 24px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  cursor: pointer;
  background: #fff;
  border: 1px solid #ccc;
  border-left: none;
  border-radius: 0 4px 4px 0;
  box-shadow: 2px 0 3px rgba(0, 0, 0, 0.1);
  visibility: hidden;
  color: #333;
}
.mapml-search-panel button.mapml-search-close svg {
  display: block;
}
.mapml-search-panel-open button.mapml-search-close {
  visibility: visible;
}
`;
