/**
 * `TemplatedFeaturesOrTilesLayer` — the OpenLayers analog of MapML.js
 * `src/mapml/layers/TemplatedFeaturesOrTilesLayer.js`. It backs a
 * `<map-link rel="features" tref="...">`: on the initial add and every map
 * `moveend` it substitutes the current view (bounds/size/zoom) into the `tref`,
 * fetches the `text/mapml` response, and grafts the returned content into the
 * LINK's own shadow root. A single templated response may mix `<map-tile>` and
 * `<map-feature>` elements (alongside `map-meta`/`map-style`/`map-link`) — a
 * GeoServer layer-group with rasters is the canonical case — which is why, like
 * the reference, this is a features-OR-tiles layer. The grafted elements render
 * themselves (the MAP-LINK branches of `map-feature.js`/`map-tile.js`
 * connectedCallback), so this controller only fetches + grafts, matching MapML.js.
 *
 * Rendering is re-architected onto OpenLayers rather than Leaflet's SVG/Grid
 * renderers, but the LayerGroup shape is preserved: this controller owns ONE
 * `ol/layer/Group` (`_group`, nested in the owning `<map-extent>`'s group so it
 * inherits visibility/opacity/z-order) whose children VARY — a `MapFeatureLayer`
 * for each contiguous `<map-feature>` run, a `MapTileLayer` for each contiguous
 * `<map-tile>` run. The grafted elements look up / create their sub-layer via
 * the link's position-keyed `_layerRegistry` (`calculatePosition`), so an
 * interleaved response keeps DOM-order stacking (zIndex = position). This is the
 * OL analog of MapML.js's `TemplatedFeaturesOrTilesLayer` (a Leaflet LayerGroup
 * whose `_layers[]` hold MapFeatureLayer/MapTileLayer instances by position).
 */
import LayerGroup from 'ol/layer/Group.js';
import { MapFeatureLayer } from './MapFeatureLayer.js';
import { toBounds as bounds } from '../geometry/Bounds.js';
import { toPoint as point } from '../geometry/Point.js';

// Substitute `{name}` tokens, invoking function-valued members (select/hidden
// query vars). Port of Leaflet's `Util.template` used by the reference layer.
function template(str, data) {
  return str.replace(/\{ *([\w_ -]+) *\}/g, (match, key) => {
    let value = data[key];
    if (value === undefined) {
      return match;
    }
    if (typeof value === 'function') {
      value = value();
    }
    return value;
  });
}

export class TemplatedFeaturesOrTilesLayer {
  constructor(linkEl, templateVars, options) {
    this._linkEl = linkEl;
    this._template = templateVars;
    this._viewer = options.viewer;
    this._map = this._viewer.map;
    this._projection = options.projection;
    this.zoomBounds = options.zoomBounds;
    // PCRS Bounds of the template's declared extent (from the map-link inputs).
    this.extentBounds = options.extentBounds;
    this._param = this._setUpTemplateVars(templateVars);
    // Position-keyed sub-layers (MapFeatureLayer | MapTileLayer) live in this
    // ol/layer/Group; the grafted <map-feature>/<map-tile> elements create and
    // register them via the link's `_layerRegistry`, so an interleaved response
    // (tile-run, feature-run, tile-run…) keeps DOM z-order. This is the OL
    // analog of MapML.js's TemplatedFeaturesOrTilesLayer (a Leaflet LayerGroup).
    this._group = new LayerGroup({ layers: [] });
    this._group.setZIndex(options.zIndex);
    // Author <map-style>/<map-link rel=stylesheet> contributions grafted with
    // the response, replayed into every feature sub-layer (present and future).
    this._styleContributors = [];
    this._onMoveEnd = this._onMoveEnd.bind(this);
    this._map.on('moveend', this._onMoveEnd);
    void this._load();
  }

  // The ol/layer/Group nested into the extent's group.
  getLayer() {
    return this._group;
  }

  // Add a position-keyed sub-layer (feature or tile) to the group. Replays any
  // grafted style contributions into a new feature sub-layer so styles that
  // arrived before it still apply. Called by map-feature/map-tile.
  addLayer(subLayer) {
    this._group.getLayers().push(subLayer);
    if (subLayer instanceof MapFeatureLayer) {
      for (const contributor of this._styleContributors) {
        subLayer.renderStyles(contributor);
      }
    }
  }

  removeLayer(subLayer) {
    this._group.getLayers().remove(subLayer);
  }

  // Style fan-out: a grafted <map-style>/<map-link rel=stylesheet> targets the
  // controller; apply it to every feature sub-layer and remember it for ones
  // created later. Ported from MapML.js TemplatedFeaturesOrTilesLayer.renderStyles.
  renderStyles(styleOrLink) {
    this._styleContributors.push(styleOrLink);
    for (const layer of this._featureLayers()) {
      layer.renderStyles(styleOrLink);
    }
  }

  _restyleFeatures() {
    for (const layer of this._featureLayers()) {
      layer._restyleFeatures();
    }
  }

  _featureLayers() {
    return this._group
      .getLayers()
      .getArray()
      .filter((l) => l instanceof MapFeatureLayer);
  }

  // Only fetch/render when the current zoom is within the template's zoom
  // bounds and its extent overlaps the view. Ported from
  // TemplatedFeaturesOrTilesLayer.isVisible (OL's view extent is already PCRS).
  isVisible() {
    const zoom = Math.round(this._map.getView().getZoom());
    if (zoom < this.zoomBounds.minZoom || zoom > this.zoomBounds.maxZoom) {
      return false;
    }
    const [minX, minY, maxX, maxY] = this._map
      .getView()
      .calculateExtent(this._map.getSize());
    const viewBounds = bounds(point(minX, minY), point(maxX, maxY));
    return this.extentBounds.overlaps(viewBounds);
  }

  redraw() {
    void this._load();
  }

  _onMoveEnd() {
    void this._load();
  }

  // Discard the previously rendered content and empty the link's shadow root,
  // mirroring TemplatedFeaturesOrTilesLayer._onMoveEnd's clean-up. Emptying the
  // shadow root first lets each grafted <map-feature>/<map-tile> self-remove
  // (its disconnectedCallback drops its sub-layer + registry entry); clearing
  // the group, registry and style contributors is a belt-and-suspenders reset.
  _clear() {
    if (this._linkEl.shadowRoot) {
      this._linkEl.shadowRoot.replaceChildren();
    }
    this._group.getLayers().clear();
    this._linkEl._layerRegistry?.clear();
    this._styleContributors = [];
  }

  // Substitute the current view into `tref`. width/height are the map size in
  // CSS pixels; left/right/top/bottom are the view extent in PCRS metres (the
  // view projection). Ported from TemplatedFeaturesOrTilesLayer._onMoveEnd.
  _buildUrl() {
    const view = this._map.getView();
    const size = this._map.getSize();
    const zoom = Math.round(view.getZoom());
    const [minX, minY, maxX, maxY] = view.calculateExtent(size);
    const p = this._param;
    const obj = {};
    if (p.zoom) obj[p.zoom] = zoom;
    if (p.width) obj[p.width] = size[0];
    if (p.height) obj[p.height] = size[1];
    if (p.left) obj[p.left] = minX;
    if (p.right) obj[p.right] = maxX;
    if (p.top) obj[p.top] = maxY;
    if (p.bottom) obj[p.bottom] = minY;
    const reserved = [
      'width',
      'height',
      'left',
      'right',
      'top',
      'bottom',
      'zoom'
    ];
    for (const v in p) {
      if (reserved.indexOf(v) < 0) {
        obj[v] = typeof p[v] === 'function' ? p[v]() : p[v];
      }
    }
    return template(this._template.template, obj);
  }

  async _load() {
    // Guard against overlapping loads: multiple moveends (e.g. while a remote
    // <map-layer src> settles) can start several _loads whose fetches resolve
    // out of order. Each captures a token; a fetch that resolves after a newer
    // _load began is stale and must not graft, else both grafts stack into the
    // shadow root (duplicate tile/feature runs at positions 3,4…).
    const token = (this._loadToken = (this._loadToken || 0) + 1);
    this._clear();
    if (!this.isVisible()) {
      return;
    }
    const url = this._buildUrl();
    let text;
    try {
      const response = await fetch(url, {
        redirect: 'follow',
        headers: new Headers({ Accept: 'text/mapml' })
      });
      text = await response.text();
    } catch (error) {
      console.log(error);
      return;
    }
    if (token !== this._loadToken) {
      return;
    }
    const mapml = new DOMParser().parseFromString(text, 'application/xml');
    if (mapml.querySelector('parsererror')) {
      return;
    }
    const frag = document.createDocumentFragment();
    // Legal content mirrors the reference query (map-extent excluded).
    const legal = mapml.querySelectorAll(
      'map-head > map-link, map-body > map-link, ' +
        'map-head > map-meta, map-body > map-meta, ' +
        'map-head > map-style, map-body > map-style, ' +
        'map-tile, map-feature'
    );
    for (const el of legal) {
      frag.appendChild(el);
    }
    if (!this._linkEl.shadowRoot) {
      return;
    }
    // Grafting the <map-feature>s triggers their connectedCallback, which
    // renders each into this link's feature layer (the MAP-LINK branch of
    // map-feature.js). The controller only fetches + grafts.
    this._linkEl.shadowRoot.appendChild(frag);
  }

  destroy() {
    this._map.un('moveend', this._onMoveEnd);
    this._clear();
  }

  // Port of TemplatedFeaturesOrTilesLayer._setUpTemplateVars: build a `param`
  // map keyed role -> author input NAME (width/height/zoom, left/right/top/
  // bottom by axis+position, plus function-valued select/hidden variables).
  _setUpTemplateVars(templateVars) {
    const param = {};
    const inputs = templateVars.values;
    for (let i = 0; i < inputs.length; i++) {
      const type = inputs[i].getAttribute('type'),
        units = inputs[i].getAttribute('units'),
        axis = inputs[i].getAttribute('axis'),
        name = inputs[i].getAttribute('name'),
        position = inputs[i].getAttribute('position'),
        select = inputs[i].tagName.toLowerCase() === 'map-select';
      if (type === 'width') {
        param.width = name;
      } else if (type === 'height') {
        param.height = name;
      } else if (type === 'zoom') {
        param.zoom = name;
      } else if (
        type === 'location' &&
        (units === 'pcrs' || units === 'gcrs')
      ) {
        switch (axis) {
          case 'x':
          case 'longitude':
          case 'easting':
            if (position) {
              if (position.match(/.*?-left/i)) {
                param.left = name;
              } else if (position.match(/.*?-right/i)) {
                param.right = name;
              }
            }
            break;
          case 'y':
          case 'latitude':
          case 'northing':
            if (position) {
              if (position.match(/top-.*?/i)) {
                param.top = name;
              } else if (position.match(/bottom-.*?/i)) {
                param.bottom = name;
              }
            }
            break;
        }
      } else if (select) {
        const parsedselect = inputs[i];
        param[name] = function () {
          return parsedselect.htmlselect?.value;
        };
      } else {
        const input = inputs[i];
        param[name] = function () {
          return input.getAttribute('value');
        };
      }
    }
    return param;
  }
}
