/**
 * `<map-a>` — a hyperlink that wraps a `<map-geometry>` (or a geometry shape /
 * sub-ring) inside a `<map-feature>`. Ported from MapML.js `src/map-a.js`.
 *
 * The element itself is a thin attribute surface (`href`/`target`/`type`/
 * `inplace`); the link behaviour lives in the feature renderer. When a
 * `<map-a href>` wraps a geometry, `parseGeometry` extracts the link and stamps
 * it on the rendered `ol/Feature`, and `FeatureInteraction` / `map-feature`
 * dispatch it through `Util._handleLink` on click (the OL analog of MapML.js's
 * `Path.attachLinkHandler`, since OL draws features to a canvas with no
 * per-feature DOM to attach listeners to).
 */
export class HTMLAnchorElement extends HTMLElement {
  static get observedAttributes() {
    return ['href', 'target', 'type', 'inplace'];
  }
  get href() {
    return this.hasAttribute('href') ? this.getAttribute('href') : '';
  }
  set href(url) {
    this.setAttribute('href', url);
  }
  get target() {
    return this.hasAttribute('target') ? this.getAttribute('target') : '';
  }
  set target(val) {
    this.setAttribute('target', val);
  }
  get type() {
    return this.hasAttribute('type') ? this.getAttribute('type') : '';
  }
  set type(val) {
    this.setAttribute('type', val);
  }
  get inplace() {
    return this.hasAttribute('inplace');
  }
  set inplace(val) {
    if (val) {
      this.setAttribute('inplace', '');
    } else {
      this.removeAttribute('inplace');
    }
  }

  attributeChangedCallback() {
    // Attributes are read live by the feature renderer; no side effects here.
  }

  constructor() {
    // Always call super first in constructor
    super();
  }
  connectedCallback() {}
  disconnectedCallback() {}
}
