/**
 * Resolve a feature's OpenLayers style from a hidden SVG "probe" element via
 * the browser's CSS engine.
 *
 * MapML.js styles features by injecting the author's `<map-style>` /
 * `<map-link rel=stylesheet>` CSS into the layer's shadow-DOM container and
 * letting it cascade onto the SVG `<path>`/`<circle>` elements Leaflet renders
 * (matched by the feature's `class`). OpenLayers renders features to a canvas
 * with no per-feature DOM, so there is nothing for the CSS to select.
 *
 * To keep the SAME authoring model (arbitrary CSS selectors over feature
 * classes) we render, per feature, a hidden probe element carrying that
 * feature's `class`/`id` into the same shadow root as the injected CSS, then
 * read `getComputedStyle(probe)`. The SVG presentation properties (stroke,
 * fill, stroke-width, …) resolve through the real cascade — author CSS beats
 * the probe's default presentation attributes exactly as it beats them on a
 * Leaflet path — and we map the result onto an `ol/style/Style`.
 */
import Style from 'ol/style/Style.js';
import Stroke from 'ol/style/Stroke.js';
import Fill from 'ol/style/Fill.js';
import CircleStyle from 'ol/style/Circle.js';

// Fold an SVG *-opacity value into a resolved CSS color string. getComputedStyle
// returns colors as `rgb(...)`/`rgba(...)`; SVG carries opacity separately.
function applyOpacity(color, opacity) {
  if (!color || color === 'none') return color;
  const o = opacity === '' || opacity == null ? 1 : Number(opacity);
  if (!Number.isFinite(o) || o >= 1) return color;
  const m = color.match(/^rgba?\(([^)]+)\)$/i);
  if (!m) return color;
  const parts = m[1].split(',').map((p) => p.trim());
  const [r, g, b] = parts;
  const a = parts.length === 4 ? Number(parts[3]) * o : o;
  return `rgba(${r}, ${g}, ${b}, ${a})`;
}

function parseDashArray(value) {
  if (!value || value === 'none') return undefined;
  const dashes = value
    .split(/[\s,]+/)
    .map((v) => parseFloat(v))
    .filter((v) => Number.isFinite(v));
  return dashes.length ? dashes : undefined;
}

function makeStroke(cs) {
  const color = cs.getPropertyValue('stroke').trim();
  if (!color || color === 'none') return undefined;
  return new Stroke({
    color: applyOpacity(color, cs.getPropertyValue('stroke-opacity').trim()),
    width: parseFloat(cs.getPropertyValue('stroke-width')) || 1,
    lineCap: cs.getPropertyValue('stroke-linecap').trim() || undefined,
    lineJoin: cs.getPropertyValue('stroke-linejoin').trim() || undefined,
    lineDash: parseDashArray(cs.getPropertyValue('stroke-dasharray').trim())
  });
}

function makeFill(cs) {
  const color = cs.getPropertyValue('fill').trim();
  if (!color || color === 'none') return undefined;
  return new Fill({
    color: applyOpacity(color, cs.getPropertyValue('fill-opacity').trim())
  });
}

// geomKind: 'point' | 'line' | 'polygon'. Returns an ol/style/Style resolved
// from the probe element's computed style.
export function resolveFeatureStyle(probeEl, geomKind) {
  const cs = getComputedStyle(probeEl);
  const stroke = makeStroke(cs);
  if (geomKind === 'point') {
    // MapML.js renders points as a fixed-size marker (featureRenderer
    // _pointToMarker) and never consults the CSS `r` property, so honour that
    // parity: keep a constant radius rather than scaling by author `r` (e.g.
    // GeoServer emits `r:48`, which would draw an enormous circle).
    return new Style({
      image: new CircleStyle({ radius: 6, stroke, fill: makeFill(cs) })
    });
  }
  if (geomKind === 'line') {
    return new Style({ stroke });
  }
  return new Style({ stroke, fill: makeFill(cs) });
}

// Map an ol/geom type to the probe/style kind (which SVG element to probe and
// which style branch to build).
export function geomKindFor(geometry) {
  const type = geometry?.getType?.();
  if (type === 'Point' || type === 'MultiPoint') return 'point';
  if (type === 'LineString' || type === 'MultiLineString') return 'line';
  return 'polygon';
}
