/**
 * `<map-span>` — an inline wrapper for a subset of coordinates, enabling
 * per-subring styling and per-coordinate links/focus. Ported from MapML.js
 * `src/map-span.js`; in this first feature slice its markup is flattened by the
 * geometry parser (subring styling lands with feature interactivity).
 */
export class HTMLSpanElement extends HTMLElement {
  static get observedAttributes() {
    return [];
  }

  attributeChangedCallback() {}
  constructor() {
    super();
  }
  connectedCallback() {}
  disconnectedCallback() {}
}
