/**
 * `SearchButton` — top-left, opt-in (`controlslist="search"`) magnifier that
 * slides in a search panel. Ported from MapML.js's
 * `src/mapml/control/SearchButton.js` (a Leaflet `Control`) to an OpenLayers
 * `ol/control/Control`.
 *
 * Behaviour ported 1:1 from upstream: the button is enabled only while a
 * *checked* `<map-layer>` advertises a `map-link[rel=search]` (a
 * MutationObserver on the viewer keeps that state live). Typing debounces a
 * `rel=suggestions` fetch; Enter (or clicking a suggestion) runs the
 * `rel=search` fetch. Both dispatch a cancelable `mapsearch`/`mapsuggestions`
 * event on the viewer whose `detail.setResults()` lets authors render their
 * own results; the default handler renders the GeoJSON responses and
 * navigates to the first feature.
 *
 * OL adaptations: Leaflet's `map.fitBounds(latLngBounds(...))` /
 * `map.setView([lat,lon],zoom)` become `view.fit(extent)` / `view.animate()`
 * after transforming the geocoder's EPSG:4326 coordinates into the view
 * projection. The panel is appended to the viewer's `.mapml-container` so it
 * slides over the map area and is subject to the `mapmlviewer` CSS container
 * query that keeps the close affordance on-screen on narrow maps.
 */
import Control from 'ol/control/Control.js';
import { transform } from 'ol/proj.js';
import { boundingExtent } from 'ol/extent.js';

const SEARCH_ICON =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="24" width="24" viewBox="0 0 15 15" fill="currentColor">' +
  '<path d="M6 0C9.31 0 12 2.69 12 6C12 7.3 11.59 8.5 10.89 9.48L14.71 13.29C15.1 13.68 15.1 14.32 14.71 14.71C14.32 15.1 13.68 15.1 13.29 14.71L9.48 10.89C8.5 11.59 7.3 12 6 12C2.69 12 0 9.31 0 6C0 2.69 2.69 0 6 0ZM6 2C3.79 2 2 3.79 2 6C2 8.21 3.79 10 6 10C8.21 10 10 8.21 10 6C10 3.79 8.21 2 6 2Z"/>' +
  '</svg>';

const CLOSE_ICON =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="18" width="18" viewBox="0 0 24 24" fill="currentColor">' +
  '<path d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6 1.41-1.41z"/>' +
  '</svg>';

export class SearchButton extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-search-control ol-control';

    super({ element: container });

    this._viewer = viewer;
    const locale = viewer.locale;

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-search-button mapml-button';
    button.setAttribute('aria-label', locale.btnSearch);
    button.title = locale.btnSearch;
    button.innerHTML = SEARCH_ICON;
    container.appendChild(button);
    this._button = button;

    // Panel lives in .mapml-container (not the control container) so it slides
    // over the whole map area and inherits the `mapmlviewer` container query.
    const panel = document.createElement('div');
    panel.className = 'mapml-search-panel';
    panel.setAttribute('hidden', '');
    viewer._container.appendChild(panel);
    this._panel = panel;

    const input = document.createElement('input');
    input.type = 'search';
    input.className = 'mapml-search-input';
    input.setAttribute('placeholder', locale.searchPlaceholder);
    input.setAttribute('aria-label', locale.btnSearch);
    panel.appendChild(input);
    this._input = input;

    const results = document.createElement('div');
    results.className = 'mapml-search-results';
    panel.appendChild(results);
    this._results = results;

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'mapml-search-close mapml-button';
    closeBtn.setAttribute('aria-label', locale.btnSearchClose);
    closeBtn.title = locale.btnSearchClose;
    closeBtn.innerHTML = CLOSE_ICON;
    panel.appendChild(closeBtn);
    this._closeBtn = closeBtn;

    this._debounceTimer = null;
    this._abortController = null;
    this._isComposing = false;

    this._onButtonClick = (e) => {
      e.stopPropagation();
      this._openPanel();
    };
    this._onButtonKeydown = (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        e.stopPropagation();
        this._openPanel();
      }
    };
    this._onInputKeydown = (e) => this._handleInputKeydown(e);
    this._onInput = () => this._handleInput();
    this._onCompositionStart = () => {
      this._isComposing = true;
    };
    this._onCompositionEnd = () => {
      this._isComposing = false;
      this._handleInput();
    };
    this._onWheel = (e) => e.stopPropagation();
    this._onCloseClick = (e) => {
      e.stopPropagation();
      this._closePanel();
    };

    button.addEventListener('click', this._onButtonClick);
    button.addEventListener('keydown', this._onButtonKeydown);
    input.addEventListener('keydown', this._onInputKeydown);
    input.addEventListener('input', this._onInput);
    input.addEventListener('compositionstart', this._onCompositionStart);
    input.addEventListener('compositionend', this._onCompositionEnd);
    panel.addEventListener('wheel', this._onWheel);
    closeBtn.addEventListener('click', this._onCloseClick);

    // Enable/disable the button as checked layers with rel=search come and go.
    this._onLoadedMetadata = () => this._updateDisabled();
    this._layerObserver = new MutationObserver((mutations) => {
      this._updateDisabled();
      for (const mutation of mutations) {
        for (const node of mutation.addedNodes) {
          if (node.nodeName && node.nodeName.toUpperCase() === 'MAP-LAYER') {
            node.addEventListener('loadedmetadata', this._onLoadedMetadata);
          }
        }
      }
    });
    this._layerObserver.observe(viewer, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['checked', 'rel']
    });
    viewer
      .querySelectorAll('map-layer')
      .forEach((layer) =>
        layer.addEventListener('loadedmetadata', this._onLoadedMetadata)
      );

    this._updateDisabled();
  }

  destroy() {
    this._layerObserver?.disconnect();
    this._viewer
      .querySelectorAll('map-layer')
      .forEach((layer) =>
        layer.removeEventListener('loadedmetadata', this._onLoadedMetadata)
      );
    this._abortController?.abort();
    if (this._debounceTimer) clearTimeout(this._debounceTimer);
    this._panel?.remove();
  }

  // --- enabled/disabled state -------------------------------------------

  _getLinks(rel) {
    const results = [];
    const layers = this._viewer.querySelectorAll('map-layer[checked]');
    for (const layer of layers) {
      const root = layer.src ? layer.shadowRoot : layer;
      const link = root?.querySelector('map-link[rel=' + rel + ']');
      if (link) results.push({ link, layer });
    }
    return results;
  }

  _hasSearchLayers() {
    return this._getLinks('search').length > 0;
  }

  _updateDisabled() {
    const enabled = this._hasSearchLayers();
    this._button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    if (!enabled && !this._panel.hasAttribute('hidden')) this._closePanel();
  }

  // --- panel open/close --------------------------------------------------

  _openPanel() {
    if (this._button.getAttribute('aria-disabled') === 'true') return;
    this._panel.removeAttribute('hidden');
    this._input.value = '';
    this._results.innerHTML = '';
    setTimeout(() => {
      this._panel.classList.add('mapml-search-panel-open');
      this._input.focus();
    }, 0);
  }

  _closePanel() {
    this._panel.classList.remove('mapml-search-panel-open');
    this._abortController?.abort();
    this._abortController = null;
    if (this._debounceTimer) {
      clearTimeout(this._debounceTimer);
      this._debounceTimer = null;
    }
    const onEnd = () => {
      this._panel.setAttribute('hidden', '');
      this._button.focus();
      this._panel.removeEventListener('transitionend', onEnd);
    };
    this._panel.addEventListener('transitionend', onEnd);
    setTimeout(onEnd, 300);
  }

  // --- input handling ----------------------------------------------------

  _handleInputKeydown(e) {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      if (this._input.value) {
        this._input.value = '';
        this._results.innerHTML = '';
      } else {
        this._closePanel();
      }
    } else if (e.key === 'Enter') {
      e.preventDefault();
      e.stopPropagation();
      if (this._debounceTimer) {
        clearTimeout(this._debounceTimer);
        this._debounceTimer = null;
      }
      this._doSearch(this._input.value.trim());
    } else if (e.key === 'ArrowDown' || e.key === 'Down') {
      e.preventDefault();
      e.stopPropagation();
      this._results.querySelector('.mapml-search-result')?.focus();
    }
  }

  _handleInput() {
    if (this._isComposing) return;
    if (this._debounceTimer) clearTimeout(this._debounceTimer);
    const query = this._input.value.trim();
    if (query.length < 2) {
      this._results.innerHTML = '';
      return;
    }
    this._debounceTimer = setTimeout(() => {
      this._fetchSuggestions(query);
    }, 300);
  }

  // --- fetch pipelines ---------------------------------------------------

  _resolveUrl(link, query) {
    const tref = link.getAttribute('tref') || '';
    const url = tref.replace('{searchTerms}', encodeURIComponent(query));
    if (link.getBase) {
      try {
        return new URL(url, link.getBase()).href;
      } catch {
        return url;
      }
    }
    return url;
  }

  _runFetches(links, query, signal) {
    return links.map(({ link, layer }) => {
      const url = this._resolveUrl(link, query);
      return fetch(url, { signal })
        .then((r) => r.json())
        .then((data) => ({ data, link, layer }));
    });
  }

  _fetchSuggestions(query) {
    if (this._button.getAttribute('aria-disabled') === 'true') return;
    const links = this._getLinks('suggestions');
    if (links.length === 0) return;

    this._abortController?.abort();
    this._abortController = new AbortController();
    const signal = this._abortController.signal;

    Promise.allSettled(this._runFetches(links, query, signal)).then(
      (settled) => {
        if (signal.aborted) return;
        const responses = settled
          .filter((s) => s.status === 'fulfilled')
          .map((s) => s.value);
        const event = new CustomEvent('mapsuggestions', {
          bubbles: true,
          cancelable: true,
          detail: {
            query,
            responses,
            setResults: this._setResults.bind(this)
          }
        });
        if (this._viewer.dispatchEvent(event)) this._renderResults(responses);
      }
    );
  }

  _doSearch(query) {
    if (!query || this._button.getAttribute('aria-disabled') === 'true') return;
    const links = this._getLinks('search');
    if (links.length === 0) return;

    this._abortController?.abort();
    this._abortController = new AbortController();
    const signal = this._abortController.signal;

    Promise.allSettled(this._runFetches(links, query, signal)).then(
      (settled) => {
        if (signal.aborted) return;
        const responses = settled
          .filter((s) => s.status === 'fulfilled')
          .map((s) => s.value);
        const event = new CustomEvent('mapsearch', {
          bubbles: true,
          cancelable: true,
          detail: {
            query,
            responses,
            setResults: this._setResults.bind(this)
          }
        });
        if (this._viewer.dispatchEvent(event)) {
          this._defaultSearchHandler(responses);
        }
      }
    );
  }

  _defaultSearchHandler(responses) {
    this._renderResults(responses);
    for (const { data } of responses) {
      if (!data || !data.features) continue;
      const feature = data.features[0];
      if (feature) {
        this._navigateToFeature(feature);
        break;
      }
    }
    this._input.focus();
  }

  // --- rendering ---------------------------------------------------------

  _renderResults(responses) {
    this._results.innerHTML = '';
    for (const { data, layer } of responses) {
      if (!data || !data.features) continue;
      for (const feature of data.features) {
        const btn = document.createElement('button');
        btn.className = 'mapml-search-result';
        btn.type = 'button';
        btn.textContent = this._formatResultName(feature.properties);
        btn.addEventListener('click', () =>
          this._selectResult(feature, layer)
        );
        btn.addEventListener('keydown', (e) => this._resultKeydown(e));
        this._results.appendChild(btn);
      }
    }
  }

  _resultKeydown(e) {
    const btn = e.target;
    const prev = btn.previousElementSibling;
    const next = btn.nextElementSibling;
    if (['ArrowDown', 'ArrowRight', 'Down', 'Right'].includes(e.key)) {
      e.preventDefault();
      e.stopPropagation();
      if (next?.classList.contains('mapml-search-result')) next.focus();
    } else if (['ArrowUp', 'ArrowLeft', 'Up', 'Left'].includes(e.key)) {
      e.preventDefault();
      e.stopPropagation();
      if (prev?.classList.contains('mapml-search-result')) prev.focus();
      else this._input.focus();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      this._input.focus();
    }
  }

  _formatResultName(props) {
    const fallback = this._viewer.locale.searchResultWithNoName;
    if (!props) return fallback;
    if (props.display_name) return props.display_name;
    const parts = [props.name];
    for (const key of ['city', 'county', 'state', 'country']) {
      if (props[key] && props[key] !== props.name) parts.push(props[key]);
    }
    return parts.filter(Boolean).join(', ') || fallback;
  }

  _selectResult(feature) {
    const name = this._formatResultName(feature.properties);
    this._input.value = name;
    this._doSearch(name);
  }

  // Public API surfaced on the cancelable events' detail.setResults().
  _setResults(items) {
    this._results.innerHTML = '';
    if (!Array.isArray(items)) return;
    for (const item of items) {
      const btn = document.createElement('button');
      btn.className = 'mapml-search-result';
      btn.type = 'button';
      btn.textContent = item.text || '';
      btn.addEventListener('click', () => {
        if (item.value != null) {
          this._input.value = item.value;
          this._doSearch(item.value);
        } else {
          this._navigateToItem(item);
        }
      });
      btn.addEventListener('keydown', (e) => this._resultKeydown(e));
      this._results.appendChild(btn);
    }
  }

  // --- navigation (OL view) ---------------------------------------------

  _viewCode() {
    return this._viewer._map.getView().getProjection().getCode();
  }

  _fitBbox(bbox) {
    const code = this._viewCode();
    const [west, south, east, north] = bbox;
    const extent = boundingExtent([
      transform([west, south], 'EPSG:4326', code),
      transform([east, north], 'EPSG:4326', code)
    ]);
    this._viewer._map.getView().fit(extent, { duration: 250 });
  }

  _navigateToFeature(feature) {
    let bbox = feature.bbox;
    if (
      (!bbox || bbox.length !== 4) &&
      feature.properties?.extent?.length === 4
    ) {
      bbox = feature.properties.extent;
    }
    if (bbox && bbox.length === 4) {
      this._fitBbox(bbox);
    } else if (feature.geometry?.coordinates?.length >= 2) {
      const [lon, lat] = feature.geometry.coordinates;
      const zoom = feature.properties?.zoom || 14;
      this._viewer._map.getView().animate({
        center: transform([lon, lat], 'EPSG:4326', this._viewCode()),
        zoom,
        duration: 250
      });
    }
  }

  _navigateToItem(item) {
    if (item.bbox && item.bbox.length === 4) {
      this._fitBbox(item.bbox);
    } else if (item.lat != null && item.lng != null) {
      this._viewer._map.getView().animate({
        center: transform([item.lng, item.lat], 'EPSG:4326', this._viewCode()),
        zoom: 14,
        duration: 250
      });
    }
  }
}
