/**
 * `QueryHandler` — the OpenLayers analog of MapML.js
 * `src/mapml/handlers/QueryHandler.js` (a Leaflet `Handler`). On a map click
 * (or Space/Enter while the map is focused) it queries the top-most
 * *queryable* `<map-layer>` — one with an enabled `<map-link rel=query>` whose
 * bounds contain the click — by substituting the click location into each
 * query template, fetching the response, and rendering the returned
 * `<map-feature>`s into a paginated popup.
 *
 * The Leaflet-specific bits are re-architected onto OpenLayers: the click
 * `coordinate` is already in PCRS (the view projection), queried features are
 * drawn with a dedicated `MapFeatureLayer` (`ol/layer/Vector`), and the popup +
 * prev/next pagination reuse the map-level `FeatureInteraction` popup. Because
 * query responses are remote/untrusted, their `<map-properties>` are rendered
 * in a sandboxed iframe (see `FeatureInteraction.openPopup`'s `sandbox` option).
 *
 * Response formats mirror MapML.js: `text/mapml` is parsed for `<map-feature>`s,
 * GeoJSON (`application/json` / `geo+json` / `geojson`) is converted via
 * `M.geojson2mapml`, any other XML that yields `<map-feature>`s is used
 * directly, and anything else is synthesized into a single feature whose
 * properties hold the raw text/HTML.
 */
/* global M */
import { MapFeatureLayer } from '../layers/MapFeatureLayer.js';
import { toPoint as point } from '../geometry/Point.js';
import { toBounds as bounds } from '../geometry/Bounds.js';

// Determine if a GeoJSON object has projected (non-CRS:84) coordinates.
// Returns true if a "crs" member is present and non-null, or if coordinate
// values exceed CRS:84 bounds (lon [-180,180], lat [-90,90]), indicating
// meter-based projected units (e.g. from WMS GetFeatureInfo responses).
function _hasProjectedCoordinates(json) {
  if (json.crs != null) return true;
  let c = _firstCoordinate(json);
  return c !== null && (Math.abs(c[0]) > 180 || Math.abs(c[1]) > 90);
}

// Extract the first [x, y] coordinate pair from a GeoJSON object,
// drilling into FeatureCollection → Feature → Geometry → coordinates.
function _firstCoordinate(json) {
  if (!json) return null;
  let type = json.type && json.type.toUpperCase();
  if (type === 'FEATURECOLLECTION') {
    if (json.features && json.features.length > 0)
      return _firstCoordinate(json.features[0]);
  } else if (type === 'FEATURE') {
    return _firstCoordinate(json.geometry);
  } else if (json.coordinates) {
    // Unwrap nested arrays until we reach a [number, number] pair
    let coords = json.coordinates;
    while (Array.isArray(coords) && Array.isArray(coords[0])) {
      coords = coords[0];
    }
    if (coords.length >= 2 && typeof coords[0] === 'number') return coords;
  } else if (type === 'GEOMETRYCOLLECTION' && json.geometries) {
    if (json.geometries.length > 0) return _firstCoordinate(json.geometries[0]);
  }
  return null;
}

// Port of Leaflet's `Util.template`: substitute `{name}` tokens, invoking
// function-valued data members (hidden/select query vars).
function template(str, data) {
  return str.replace(/\{ *([\w_ -]+) *\}/g, (match, key) => {
    let value = data[key];
    if (value === undefined) {
      throw new Error('No value provided for variable ' + match);
    } else if (typeof value === 'function') {
      value = value(data);
    }
    return value;
  });
}

export class QueryHandler {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    // Current query result set + the currently displayed index.
    this._features = [];
    this._index = 0;
    // <map-link>s whose shadow roots hold rendered features, to clear on reset.
    this._activeLinks = new Set();

    this._onClick = this._onClick.bind(this);
    this._onKeyDown = this._onKeyDown.bind(this);
    this._onPopupClose = this._onPopupClose.bind(this);
  }

  enable() {
    this._map.on('singleclick', this._onClick);
    this._map.getViewport().addEventListener('keydown', this._onKeyDown);
    this._viewer.addEventListener('mapml:contentpopupclose', this._onPopupClose);
  }

  destroy() {
    this._map.un('singleclick', this._onClick);
    this._map.getViewport().removeEventListener('keydown', this._onKeyDown);
    this._viewer.removeEventListener(
      'mapml:contentpopupclose',
      this._onPopupClose
    );
    this._clear();
    if (this._queryLayer) {
      this._map.removeLayer(this._queryLayer);
      this._queryLayer = null;
    }
  }

  // Top-down (DOM order reversed) first queryable <map-layer>.
  _getTopQueryableLayer() {
    const layers = this._viewer.layers;
    for (let l = layers.length - 1; l >= 0; l--) {
      if (layers[l].queryable()) {
        return layers[l];
      }
    }
    return null;
  }

  _onClick(e) {
    const layerEl = this._getTopQueryableLayer();
    if (!layerEl) return;
    this._query(e.coordinate, layerEl);
  }

  // Space/Enter while the map surface is focused queries the map centre
  // (mirrors MapML.js `_queryTopLayerAtMapCenter`).
  _onKeyDown(e) {
    if (e.key !== ' ' && e.key !== 'Enter') return;
    if (e.target.closest('.ol-control')) return;
    const layerEl = this._getTopQueryableLayer();
    if (!layerEl) return;
    const center = this._map.getView().getCenter();
    if (center) this._query(center, layerEl);
  }

  _query(coordinate, layerEl) {
    const view = this._map.getView();
    const zoom = Math.round(view.getZoom());
    const projection = layerEl.getProjection();
    const crs = M[projection];
    const tileSize = crs.options.crs.tile.bounds.max.x;
    const sizeArr = this._map.getSize();
    const size = point(sizeArr[0], sizeArr[1]);

    const pcrsClick = point(coordinate[0], coordinate[1]);
    const latlng = crs.unproject(pcrsClick);

    const templates = layerEl.getQueryTemplates(pcrsClick, zoom);
    if (!templates || templates.length === 0) {
      return;
    }

    const tcrs2pcrs = (c) => crs.transformation.untransform(c, crs.scale(zoom));
    const tcrs2gcrs = (c) =>
      crs.unproject(crs.transformation.untransform(c, crs.scale(zoom)));

    const tcrsClickLoc = crs.latLngToPoint(latlng, zoom);
    const tileMatrixClickLoc = tcrsClickLoc.divideBy(tileSize).floor();
    const tileBounds = bounds(
      tcrsClickLoc.divideBy(tileSize).floor().multiplyBy(tileSize),
      tcrsClickLoc.divideBy(tileSize).ceil().multiplyBy(tileSize)
    );

    const fetches = [];
    for (const tmpl of templates) {
      const obj = {};
      const q = tmpl.query;

      obj[q.tilei] = tcrsClickLoc.x.toFixed() - tileMatrixClickLoc.x * tileSize;
      obj[q.tilej] = tcrsClickLoc.y.toFixed() - tileMatrixClickLoc.y * tileSize;

      // the click is forced to the centre of the map in the layer crs
      obj[q.mapi] = size.divideBy(2).x.toFixed();
      obj[q.mapj] = size.divideBy(2).y.toFixed();

      obj[q.pixelleft] = crs.pointToLatLng(tcrsClickLoc, zoom).lng;
      obj[q.pixeltop] = crs.pointToLatLng(tcrsClickLoc, zoom).lat;
      obj[q.pixelright] = crs.pointToLatLng(tcrsClickLoc.add([1, 1]), zoom).lng;
      obj[q.pixelbottom] = crs.pointToLatLng(tcrsClickLoc.add([1, 1]), zoom).lat;

      obj[q.column] = tileMatrixClickLoc.x;
      obj[q.row] = tileMatrixClickLoc.y;
      obj[q.x] = tcrsClickLoc.x.toFixed();
      obj[q.y] = tcrsClickLoc.y.toFixed();

      obj[q.easting] = tcrs2pcrs(tcrsClickLoc).x;
      obj[q.northing] = tcrs2pcrs(tcrsClickLoc).y;
      obj[q.longitude] = tcrs2gcrs(tcrsClickLoc).lng;
      obj[q.latitude] = tcrs2gcrs(tcrsClickLoc).lat;
      obj[q.zoom] = zoom;
      obj[q.width] = size.x;
      obj[q.height] = size.y;

      // assumes the click is at the centre of the map (per mapi, mapj above)
      obj[q.mapbottom] = tcrs2pcrs(tcrsClickLoc.add(size.divideBy(2))).y;
      obj[q.mapleft] = tcrs2pcrs(tcrsClickLoc.subtract(size.divideBy(2))).x;
      obj[q.maptop] = tcrs2pcrs(tcrsClickLoc.subtract(size.divideBy(2))).y;
      obj[q.mapright] = tcrs2pcrs(tcrsClickLoc.add(size.divideBy(2))).x;

      obj[q.tilebottom] = tcrs2pcrs(tileBounds.max).y;
      obj[q.tileleft] = tcrs2pcrs(tileBounds.min).x;
      obj[q.tiletop] = tcrs2pcrs(tileBounds.min).y;
      obj[q.tileright] = tcrs2pcrs(tileBounds.max).x;

      // copy any hidden/select variables (non-role keys) into the values
      const roles = [
        'mapi',
        'mapj',
        'tilei',
        'tilej',
        'row',
        'col',
        'x',
        'y',
        'easting',
        'northing',
        'longitude',
        'latitude',
        'width',
        'height',
        'zoom',
        'mapleft',
        'mapright',
        'maptop',
        'mapbottom',
        'tileleft',
        'tileright',
        'tiletop',
        'tilebottom',
        'pixeltop',
        'pixelbottom',
        'pixelleft',
        'pixelright'
      ];
      for (const v in q) {
        if (roles.indexOf(v) < 0) {
          obj[v] = q[v];
        }
      }
      fetches.push(this._fetchFeatures(tmpl, obj, latlng, projection));
    }

    Promise.allSettled(fetches).then((results) => {
      const features = [];
      for (const r of results) {
        if (r.status === 'fulfilled' && r.value) {
          for (const feature of r.value.features) {
            feature._linkEl = r.value.template.linkEl;
          }
          features.push(...r.value.features);
        }
      }
      if (features.length > 0) {
        this._displayFeatures(features, coordinate, projection);
      }
    });
  }

  _fetchFeatures(tmpl, obj, latlng, projection) {
    const parser = new DOMParser();
    const geom =
      "<map-geometry cs='gcrs'><map-point><map-coordinates>" +
      latlng.lng +
      ' ' +
      latlng.lat +
      '</map-coordinates></map-point></map-geometry>';
    return fetch(template(tmpl.template, obj), { redirect: 'follow' })
      .then((response) => {
        if (response.status >= 200 && response.status < 300) {
          return response.text().then((text) => ({
            contenttype: response.headers.get('Content-Type') || '',
            text
          }));
        }
        throw new Error(response.status);
      })
      .then((response) => {
        let features = [];
        let queryMetas = [];
        if (response.contenttype.startsWith('text/mapml')) {
          const mapmldoc = parser.parseFromString(
            response.text,
            'application/xml'
          );
          features = Array.prototype.slice.call(
            mapmldoc.querySelectorAll('map-feature')
          );
          queryMetas = Array.prototype.slice.call(
            mapmldoc.querySelectorAll(
              'map-meta[name=cs], map-meta[name=zoom], map-meta[name=projection]'
            )
          );
          this._addFallbackGeometry(features, geom, parser);
          if (queryMetas.length) features.forEach((f) => (f.meta = queryMetas));
        } else if (
          response.contenttype.startsWith('application/json') ||
          response.contenttype.startsWith('application/geo+json') ||
          response.contenttype.startsWith('application/geojson')
        ) {
          try {
            const json = JSON.parse(response.text);
            // Replace null geometries with a point at the click location so
            // geojson2mapml can process the features without error.
            const clickPoint = {
              type: 'Point',
              coordinates: [latlng.lng, latlng.lat]
            };
            if (json.type === 'FeatureCollection' && json.features) {
              for (const f of json.features) {
                if (f.geometry === null || f.geometry === undefined) {
                  f.geometry = clickPoint;
                }
              }
            } else if (json.type === 'Feature') {
              if (json.geometry === null || json.geometry === undefined) {
                json.geometry = clickPoint;
              }
            }
            const mapmlLayer = M.geojson2mapml(json, { projection });
            // if a crs member is present and non-null, or coordinate values
            // exceed CRS:84 range, the response coordinates are in the layer's
            // projected CRS, not CRS:84.
            if (_hasProjectedCoordinates(json)) {
              const csMeta = mapmlLayer.querySelector('map-meta[name=cs]');
              if (csMeta) csMeta.setAttribute('content', 'pcrs');
            }
            features = Array.prototype.slice.call(
              mapmlLayer.querySelectorAll('map-feature')
            );
            queryMetas = Array.prototype.slice.call(
              mapmlLayer.querySelectorAll(
                'map-meta[name=cs], map-meta[name=zoom], map-meta[name=projection]'
              )
            );
            this._addFallbackGeometry(features, geom, parser);
            if (queryMetas.length) features.forEach((f) => (f.meta = queryMetas));
          } catch {
            // not valid GeoJSON, fall through to HTML rendering
            features.push(this._synthesizeFeature(response.text, geom, parser));
          }
        } else {
          try {
            const featureDocument = parser.parseFromString(
              response.text,
              'application/xml'
            );
            const featureCollection =
              featureDocument.querySelectorAll('map-feature');
            if (
              featureDocument.querySelector('parsererror') ||
              featureCollection.length === 0
            ) {
              throw new Error('parsererror');
            }
            queryMetas = Array.prototype.slice.call(
              featureDocument.querySelectorAll(
                'map-meta[name=cs], map-meta[name=zoom], map-meta[name=projection]'
              )
            );
            const g = parser.parseFromString(geom, 'application/xml');
            for (const feature of featureCollection) {
              if (!feature.querySelector('map-geometry')) {
                feature.appendChild(g.firstElementChild.cloneNode(true));
              }
              feature.meta = queryMetas;
              features.push(feature);
            }
          } catch {
            features.push(
              this._synthesizeFeature(response.text, geom, parser)
            );
          }
        }
        return { features, template: tmpl, projection };
      })
      .catch((err) => {
        console.log('Looks like there was a problem. Status: ' + err.message);
        return null;
      });
  }

  // Give geometryless features a point geometry at the click location.
  _addFallbackGeometry(features, geom, parser) {
    const geometryless = features.filter((f) => !f.querySelector('map-geometry'));
    if (!geometryless.length) return;
    const g = parser.parseFromString(geom, 'application/xml');
    for (const f of geometryless) {
      f.appendChild(g.firstElementChild.cloneNode(true));
    }
  }

  // Synthesize a single <map-feature> from arbitrary text/HTML content, with a
  // point geometry at the click location. Mirrors MapML.js's fallback branch.
  _synthesizeFeature(text, geom, parser) {
    const html = parser.parseFromString(text, 'text/html');
    const featureDoc = parser.parseFromString(
      '<map-feature><map-properties></map-properties>' + geom + '</map-feature>',
      'text/html'
    );
    const properties = featureDoc.querySelector('map-properties');
    if (html.body) {
      properties.appendChild(html.querySelector('html'));
    } else {
      properties.append(text);
    }
    return featureDoc.querySelector('map-feature');
  }

  _displayFeatures(features, coordinate, projection) {
    this._clear();
    this._features = features;
    this._index = 0;
    this._ensureQueryLayer(projection);
    this._showFeature(0, coordinate);
  }

  _ensureQueryLayer(projection) {
    if (this._queryLayer && this._queryLayerProjection === projection) {
      return;
    }
    if (this._queryLayer) {
      this._map.removeLayer(this._queryLayer);
    }
    this._queryLayer = new MapFeatureLayer({
      projection,
      mapEl: this._viewer
    });
    // Draw queried features above ordinary layers.
    this._queryLayer.setZIndex(1000);
    this._queryLayerProjection = projection;
    this._map.addLayer(this._queryLayer);
  }

  _showFeature(i, coordinate) {
    const feature = this._features[i];
    if (!feature) return;
    this._index = i;
    const linkEl = feature._linkEl;

    // Rebuild the link's shadow root with this feature + its query metas so the
    // DOM reflects the currently displayed feature (matches MapML.js
    // `showPaginationFeature`).
    if (linkEl?.shadowRoot) {
      linkEl.shadowRoot.replaceChildren();
      if (feature.meta) {
        for (const m of feature.meta) {
          linkEl.shadowRoot.appendChild(m);
        }
      }
      linkEl.shadowRoot.appendChild(feature);
      this._activeLinks.add(linkEl);
    }

    // Render this feature's geometry, clearing the previous one.
    this._queryLayer.getSource().clear();
    this._queryLayer._features = [];
    // native zoom for the queried feature's coordinates
    feature._initialZoom = feature._initialZoom ?? Math.round(
      this._map.getView().getZoom()
    );
    feature._viewer = this._viewer;
    const fallbackCS = this._fallbackCS(feature);
    const olFeature = this._queryLayer.createGeometry(feature, fallbackCS);
    if (olFeature) {
      feature._olFeature = olFeature;
      this._queryLayer.addLayer(olFeature);
    }

    const total = this._features.length;
    this._viewer._featureInteraction.openPopup(feature, coordinate, {
      sandbox: true,
      paginate: {
        index: i,
        total,
        onNavigate: (delta) => {
          const next = (i + delta + total) % total;
          this._showFeature(next, coordinate);
        }
      }
    });
  }

  // Fallback cs for a queried feature's <map-geometry>: the response's
  // <map-meta name=cs>, else 'gcrs'.
  _fallbackCS(feature) {
    const csMeta = feature.meta?.find(
      (m) => (m.getAttribute('name') || '').toLowerCase() === 'cs'
    );
    return csMeta ? csMeta.getAttribute('content') : 'gcrs';
  }

  _onPopupClose() {
    this._clear();
  }

  _clear() {
    if (this._queryLayer) {
      this._queryLayer.getSource().clear();
      this._queryLayer._features = [];
    }
    for (const linkEl of this._activeLinks) {
      if (linkEl.shadowRoot) linkEl.shadowRoot.replaceChildren();
    }
    this._activeLinks.clear();
    this._features = [];
    this._index = 0;
  }
}
