/**
 * `MapTileLayer` — the OpenLayers analog of MapML.js's
 * `src/mapml/layers/MapTileLayer.js` (a Leaflet `GridLayer`). One instance
 * renders a CONTIGUOUS run of `<map-tile row col zoom src>` elements: each tile
 * is a pre-addressed image at a fixed tilematrix cell, so the run is a static
 * tile mosaic rather than a templated `{z}/{x}/{y}` source.
 *
 * Rendering is re-architected onto `ol/layer/Tile` + `ol/source/TileImage`
 * rather than Leaflet's `GridLayer`. The source's `tileUrlFunction` consults a
 * `col:row:zoom -> <map-tile>` map, returning that tile's `src` (or `undefined`
 * for cells the run doesn't cover, which OL simply leaves blank). The projection
 * + tile grid come from the same `M[projection]` tables as every other tile
 * layer (`olcrs.getProjection`/`getTileGrid`), so map zoom == tilematrix zoom
 * for OSMTILE.
 *
 * Sibling of `MapFeatureLayer`: both are position-keyed sub-layers of a
 * `<map-link rel="features">`'s `TemplatedFeaturesOrTilesLayer` group, so an
 * interleaved response (tile-run, feature-run, tile-run…) keeps DOM z-order.
 */
import TileLayer from 'ol/layer/Tile.js';
import TileImage from 'ol/source/TileImage.js';
import TileGrid from 'ol/tilegrid/TileGrid.js';
import { getProjection, getTileGrid } from '../geo/crs/olcrs.js';
import { toBounds as bounds } from '../geometry/Bounds.js';
import { toPoint as point } from '../geometry/Point.js';

const TILE_SIZE = 256;

export class MapTileLayer extends TileLayer {
  constructor(options = {}) {
    const mProj = window.M[options.projection];
    const projection = getProjection(mProj);
    // A run's <map-tile>s are pre-addressed at ONE tilematrix zoom that need
    // NOT equal the map's current integer zoom (GeoServer picks the tilematrix
    // for the request scale). Build the source on a SINGLE-resolution grid at
    // that native zoom, sharing the projection origin so tile [0,x,y] === WMTS
    // col=x,row=y at that zoom. OL then always requests exactly these cells and
    // SCALES them across every view resolution, so the fixed-zoom mosaic renders
    // at any map zoom instead of only when view-z happens to equal the tile z.
    const nativeZoom = options.nativeZoom ?? 0;
    const resolutions = mProj.options.resolutions;
    const source = new TileImage({
      projection,
      tileGrid: new TileGrid({
        extent: projection.getExtent(),
        origin: mProj.options.origin,
        resolutions: [resolutions[nativeZoom] ?? resolutions[0]],
        tileSize: TILE_SIZE
      })
    });
    super({ source });
    this._projection = options.projection;
    this._nativeZoom = nativeZoom;
    // Full pyramid, kept only for PCRS bounds math in _updateBounds.
    this._tileGrid = getTileGrid(mProj);
    // <map-tile> elements added to this run, and a col:row:zoom -> element map.
    this._mapTiles = options.mapTiles || [];
    this._tileMap = {};
    this._buildTileMap();
    // OL requests cells at the single grid level (z 0); resolve x/y against the
    // run's native zoom to the matching <map-tile>'s src (undefined = blank).
    source.setTileUrlFunction((tileCoord) => {
      if (!tileCoord) return undefined;
      const [, x, y] = tileCoord;
      const mapTile = this._tileMap[`${x}:${y}:${this._nativeZoom}`];
      return mapTile ? mapTile.src : undefined;
    });
    if (options.zIndex !== undefined) {
      this.setZIndex(options.zIndex);
    }
    this._updateBounds();
  }

  addMapTile(mapTile) {
    if (!this._mapTiles.includes(mapTile)) {
      this._mapTiles.push(mapTile);
      this._addToTileMap(mapTile);
      this._updateBounds();
      // Drop any cached blank tile so OL re-requests this newly covered cell.
      this.getSource().refresh();
    }
  }

  removeMapTile(mapTile) {
    const index = this._mapTiles.indexOf(mapTile);
    if (index !== -1) {
      this._mapTiles.splice(index, 1);
      this._removeFromTileMap(mapTile);
      this._updateBounds();
      this.getSource().refresh();
    }
  }

  // Whether the run is within zoom range and overlaps the current view. Ported
  // from MapTileLayer.isVisible; OL's view extent is already PCRS. NB: named
  // `_isVisible` (not `isVisible`) because ol/layer/Layer already defines an
  // `isVisible(view)` used by getAttributions — overriding it with a
  // (map)-signature method breaks the attribution control (it passes a view).
  _isVisible(map) {
    if (!this.layerBounds || !this.zoomBounds) return false;
    const view = map.getView();
    const zoom = Math.round(view.getZoom());
    if (zoom < this.zoomBounds.minZoom || zoom > this.zoomBounds.maxZoom) {
      return false;
    }
    const [minX, minY, maxX, maxY] = view.calculateExtent(map.getSize());
    return this.layerBounds.overlaps(bounds(point(minX, minY), point(maxX, maxY)));
  }

  _buildTileMap() {
    this._tileMap = {};
    for (const mapTile of this._mapTiles) {
      this._addToTileMap(mapTile);
    }
  }

  _addToTileMap(mapTile) {
    this._tileMap[`${mapTile.col}:${mapTile.row}:${mapTile.zoom}`] = mapTile;
  }

  _removeFromTileMap(mapTile) {
    delete this._tileMap[`${mapTile.col}:${mapTile.row}:${mapTile.zoom}`];
  }

  // Union of the run's tile extents (PCRS, via the tile grid) + its zoom span.
  // Read by the registry/debug and HTMLLayerElement bounds aggregation.
  _updateBounds() {
    let bnds, zoomBounds;
    for (const mapTile of this._mapTiles) {
      const [minX, minY, maxX, maxY] = this._tileGrid.getTileCoordExtent([
        mapTile.zoom,
        mapTile.col,
        mapTile.row
      ]);
      if (!bnds) {
        bnds = bounds(point(minX, minY), point(maxX, maxY));
      } else {
        bnds.extend(point(minX, minY));
        bnds.extend(point(maxX, maxY));
      }
      if (!zoomBounds) {
        zoomBounds = {
          minZoom: mapTile.zoom,
          maxZoom: mapTile.zoom,
          minNativeZoom: mapTile.zoom,
          maxNativeZoom: mapTile.zoom
        };
      } else {
        zoomBounds.minZoom = Math.min(zoomBounds.minZoom, mapTile.zoom);
        zoomBounds.maxZoom = Math.max(zoomBounds.maxZoom, mapTile.zoom);
        zoomBounds.minNativeZoom = Math.min(
          zoomBounds.minNativeZoom,
          mapTile.zoom
        );
        zoomBounds.maxNativeZoom = Math.max(
          zoomBounds.maxNativeZoom,
          mapTile.zoom
        );
      }
    }
    this.layerBounds = bnds;
    this.zoomBounds = zoomBounds;
  }
}
