/**
 * `FeatureIndex` — keyboard/screen-reader access to canvas-rendered features.
 *
 * MapML.js gets feature focus "for free": its Leaflet SVG `featureRenderer`
 * produces a focusable `<g>`/`<path>` per `<map-feature>`, and
 * `src/mapml/handlers/FeatureIndex.js` sorts those DOM nodes by distance to the
 * map centre, hands the nearest `tabindex="0"`, and arrow-navigates between
 * them. OpenLayers draws vectors to a canvas — there is no per-feature DOM to
 * focus — so this handler is the re-architected analog. It mirrors MapML.js's
 * `FeatureIndex` semantics (in-view membership, distance sort, `currentIndex`,
 * arrow-key nav with wrap, popup prev/next clamp) but supplies the missing DOM:
 * a container of 1×1 focusable `<button>` proxies positioned over each feature
 * (the same device MapML-MapLibre's `FeatureFocusIndex` uses on its canvas).
 *
 * One proxy at a time holds `tabindex="0"` (the nearest-to-centre feature); the
 * rest are `tabindex="-1"` and reachable only via the arrow keys. A separate
 * focus ring overlay frames the focused feature for sighted keyboard users.
 * The proxies re-sort on `moveend`/layer changes and re-position each frame so
 * they track the feature during pans and zooms.
 */
import { containsCoordinate, getCenter } from 'ol/extent.js';

export class FeatureIndex {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    // Sorted (nearest-to-centre first) array of
    // { featureEl, olFeature, center:[x,y], proxy }.
    this._sorted = [];
    this._currentIndex = 0;
    // featureEl -> proxy <button>, reused across refreshes to preserve focus.
    this._proxies = new Map();
    // Subscribers (the FeatureIndexOverlay) notified when the in-view set
    // changes, so the reticle overlay re-reads a fresh, current set.
    this._entriesListeners = new Set();

    this._container = document.createElement('div');
    this._container.className = 'mapml-feature-focus-layer';
    this._container.setAttribute('aria-hidden', 'false');

    this._focusRing = document.createElement('div');
    this._focusRing.className = 'mapml-feature-focus-ring';
    this._focusRing.setAttribute('aria-hidden', 'true');
    this._focusRing.style.display = 'none';
    this._container.appendChild(this._focusRing);

    // Insert the proxy layer after the map canvas but before OL's control
    // container (.ol-overlaycontainer-stopevent), so the natural tab order is
    // map -> nearest feature -> controls (features are the first tab stop), and
    // the focus ring still paints above the canvas. Mirrors MapML-MapLibre's
    // placement of its FeatureFocusIndex container between canvas and controls.
    const viewport = this._map.getViewport();
    const controls = viewport.querySelector('.ol-overlaycontainer-stopevent');
    viewport.insertBefore(this._container, controls);

    this._onMoveEnd = () => this.scheduleRefresh();
    this._onPostRender = () => this._reposition();
    this._onLayersChanged = () => this.scheduleRefresh();
    this._onKeyDown = this._onKeyDown.bind(this);
    this._onFocusIn = this._onFocusIn.bind(this);
    this._onFocusOut = this._onFocusOut.bind(this);

    this._map.on('moveend', this._onMoveEnd);
    this._map.on('postrender', this._onPostRender);
    this._viewer.addEventListener('mapml:layerschanged', this._onLayersChanged);
    this._container.addEventListener('keydown', this._onKeyDown);
    this._container.addEventListener('focusin', this._onFocusIn);
    this._container.addEventListener('focusout', this._onFocusOut);

    this.scheduleRefresh();
  }

  destroy() {
    this._destroyed = true;
    this._map.un('moveend', this._onMoveEnd);
    this._map.un('postrender', this._onPostRender);
    this._viewer.removeEventListener(
      'mapml:layerschanged',
      this._onLayersChanged
    );
    this._container.remove();
    this._proxies.clear();
    this._entriesListeners.clear();
    this._sorted = [];
  }

  // Coalesce bursts of feature/layer/view changes into a single refresh on the
  // next animation frame (by which point the map has a rendered frame state, so
  // getPixelFromCoordinate is usable).
  scheduleRefresh() {
    if (this._refreshScheduled || this._destroyed) return;
    this._refreshScheduled = true;
    requestAnimationFrame(() => {
      this._refreshScheduled = false;
      if (!this._destroyed) this._refresh();
    });
  }

  // Every ol/Feature that belongs to a <map-feature> in a currently-visible
  // layer, walking nested ol/layer/Groups.
  _collectFeatures() {
    const out = [];
    const walk = (layers) => {
      for (const layer of layers) {
        if (layer.getVisible && !layer.getVisible()) continue;
        if (layer.getLayers) {
          walk(layer.getLayers().getArray());
        } else if (layer.getSource?.()?.getFeatures) {
          for (const f of layer.getSource().getFeatures()) {
            if (f._featureEl) out.push({ olFeature: f, featureEl: f._featureEl });
          }
        }
      }
    };
    walk(this._map.getLayers().getArray());
    return out;
  }

  _featureCaption(featureEl) {
    const caption = featureEl.querySelector('map-featurecaption');
    return caption ? caption.textContent : this._viewer.locale.dfFeatureCaption;
  }

  _createProxy(featureEl) {
    const proxy = document.createElement('button');
    proxy.type = 'button';
    proxy.className = 'mapml-feature-focus-proxy';
    proxy.tabIndex = -1;
    proxy._featureEl = featureEl;
    return proxy;
  }

  // Recompute in-view membership, sort by distance to the map centre, and
  // sync the proxy DOM. Nearest feature becomes the single tab stop.
  //
  // Membership and distance are computed in map (PCRS) coordinates, mirroring
  // MapML.js FeatureIndex (`_mapPCRSBounds`/centre distance). Working in
  // coordinate space (not pixels) means this never calls
  // getPixelFromCoordinate, which returns null before the first rendered frame
  // (e.g. when a feature is added to a fresh layer) and would throw.
  _refresh() {
    const view = this._map.getView();
    const size = this._map.getSize();
    const centerCoord = view.getCenter();
    if (!size || !centerCoord) return;
    const extent = view.calculateExtent(size);
    const zoom = Math.round(view.getZoom());
    const [cx, cy] = centerCoord;

    const candidates = [];
    for (const { olFeature, featureEl } of this._collectFeatures()) {
      if (zoom < featureEl.min || zoom > featureEl.max) continue;
      const center = getCenter(olFeature.getGeometry().getExtent());
      if (!containsCoordinate(extent, center)) continue;
      const dx = center[0] - cx;
      const dy = center[1] - cy;
      candidates.push({ featureEl, olFeature, center, _dist: dx * dx + dy * dy });
    }
    candidates.sort((a, b) => a._dist - b._dist);

    // Sync proxies: reuse existing, create new, drop gone.
    const seen = new Set();
    for (const entry of candidates) {
      let proxy = this._proxies.get(entry.featureEl);
      if (!proxy) {
        proxy = this._createProxy(entry.featureEl);
        this._proxies.set(entry.featureEl, proxy);
      }
      proxy.setAttribute('aria-label', this._featureCaption(entry.featureEl));
      entry.proxy = proxy;
      seen.add(entry.featureEl);
    }
    for (const [el, proxy] of this._proxies) {
      if (!seen.has(el)) {
        proxy.remove();
        this._proxies.delete(el);
      }
    }

    this._sorted = candidates;
    // DOM order = tab order: ring first, then proxies nearest-to-centre.
    this._container.replaceChildren(
      this._focusRing,
      ...candidates.map((e) => e.proxy)
    );
    // Only the nearest feature is a tab stop (matches MapML.js _sortIndex).
    candidates.forEach((e, i) => {
      e.proxy.tabIndex = i === 0 ? 0 : -1;
    });
    this._currentIndex = 0;
    this._reposition();
    this._notifyEntriesChanged();
  }

  // --- FeatureIndexOverlay host API ---

  // Subscribe to in-view-set changes; returns an unsubscribe function. The
  // overlay listens here rather than to `moveend` so it always reads the
  // freshly-recomputed set (refresh is rAF-debounced, one frame after the
  // event) and also picks up feature add/remove, which don't fire `moveend`.
  onEntriesChanged(listener) {
    this._entriesListeners.add(listener);
    return () => this._entriesListeners.delete(listener);
  }

  _notifyEntriesChanged() {
    for (const listener of this._entriesListeners) listener();
  }

  // The in-view features, nearest-to-centre first, as { label, extent (view
  // projection coords), activate() } — the data the reticle overlay indexes.
  getInboundEntries() {
    return this._sorted.map((entry) => ({
      label: this._featureCaption(entry.featureEl),
      extent: entry.olFeature.getGeometry().getExtent(),
      activate: () => this._activateFeature(entry.featureEl)
    }));
  }

  // Number-key activation from the overlay: open the feature's popup if it has
  // <map-properties>, otherwise focus it (mirrors MapML.js FeatureIndexOverlay
  // `_onKeyDown`: popup if present, else focus the feature group).
  _activateFeature(featureEl) {
    if (featureEl.querySelector('map-properties')) {
      this._viewer._featureInteraction?.closePopup();
      this._viewer._featureInteraction?.openPopup(featureEl);
    } else {
      // Dismiss any popup left open by a previously activated feature, so it
      // isn't mistaken for this (property-less) feature's popup.
      this._viewer._featureInteraction?.closePopup();
      this.focusFeature(featureEl);
    }
  }

  // Position every proxy over its feature's projected centre, and reflow the
  // focus ring if a feature is focused. Runs each rendered frame so proxies
  // track the feature during animated pans/zooms.
  _reposition() {
    for (const entry of this._sorted) {
      const pixel = this._map.getPixelFromCoordinate(entry.center);
      if (!pixel) continue;
      entry.proxy.style.left = `${Math.round(pixel[0])}px`;
      entry.proxy.style.top = `${Math.round(pixel[1])}px`;
    }
    if (this._focusRing.style.display !== 'none') {
      const entry = this._sorted[this._currentIndex];
      if (entry) this._reflowFocusRing(entry);
    }
  }

  _reflowFocusRing(entry) {
    const [minX, minY, maxX, maxY] = entry.olFeature.getGeometry().getExtent();
    const tl = this._map.getPixelFromCoordinate([minX, maxY]);
    const br = this._map.getPixelFromCoordinate([maxX, minY]);
    if (!tl || !br) return;
    let left = Math.min(tl[0], br[0]);
    let top = Math.min(tl[1], br[1]);
    let width = Math.abs(br[0] - tl[0]);
    let height = Math.abs(br[1] - tl[1]);
    // Give point features a visible ring rather than a zero-size box.
    const MIN = 24;
    if (width < MIN) {
      left -= (MIN - width) / 2;
      width = MIN;
    }
    if (height < MIN) {
      top -= (MIN - height) / 2;
      height = MIN;
    }
    const ring = this._focusRing;
    ring.style.left = `${Math.round(left)}px`;
    ring.style.top = `${Math.round(top)}px`;
    ring.style.width = `${Math.round(width)}px`;
    ring.style.height = `${Math.round(height)}px`;
  }

  _indexOfProxy(proxy) {
    return this._sorted.findIndex((e) => e.proxy === proxy);
  }

  _focusEntry(i, options) {
    const entry = this._sorted[i];
    if (!entry) return;
    this._currentIndex = i;
    entry.proxy.focus(options);
  }

  // Focus a specific feature's proxy (used to return focus from a closing
  // popup, and by map-feature.focus()). Returns false when the feature is no
  // longer indexed/in view.
  focusFeature(featureEl, options) {
    const i = this._sorted.findIndex((e) => e.featureEl === featureEl);
    if (i < 0) return false;
    this._focusEntry(i, options);
    return true;
  }

  // Blur a feature's proxy and return focus to the map, but only while that
  // proxy actually holds focus. Ported from MapML.js map-feature.js blur.
  blurFeature(featureEl) {
    const entry = this._sorted.find((e) => e.featureEl === featureEl);
    if (!entry) return;
    if (this._viewer.shadowRoot.activeElement === entry.proxy) {
      entry.proxy.blur();
      this._viewer.focus();
    }
  }

  _onFocusIn(e) {
    const i = this._indexOfProxy(e.target);
    if (i < 0) return;
    this._currentIndex = i;
    this._focusRing.style.display = 'block';
    this._reflowFocusRing(this._sorted[i]);
  }

  _onFocusOut(e) {
    // Ignore focus moving between our own proxies.
    if (e.relatedTarget && this._container.contains(e.relatedTarget)) return;
    this._focusRing.style.display = 'none';
    // Reset the tab entry point to the nearest feature (matches the Tab-reset
    // in MapML.js geometry.js _handleFocus).
    if (this._sorted.length) {
      this._sorted.forEach((entry, i) => {
        entry.proxy.tabIndex = i === 0 ? 0 : -1;
      });
      this._currentIndex = 0;
    }
  }

  _onKeyDown(e) {
    if (!this._sorted.length) return;
    const last = this._sorted.length - 1;
    switch (e.key) {
      case 'ArrowLeft':
      case 'ArrowUp':
        e.preventDefault();
        e.stopPropagation();
        this._focusEntry(this._currentIndex === 0 ? last : this._currentIndex - 1);
        break;
      case 'ArrowRight':
      case 'ArrowDown':
        e.preventDefault();
        e.stopPropagation();
        this._focusEntry(this._currentIndex === last ? 0 : this._currentIndex + 1);
        break;
      case 'Enter':
      case ' ':
      case 'Spacebar':
        e.preventDefault();
        e.stopPropagation();
        this._sorted[this._currentIndex]?.featureEl.click();
        break;
      case 'Escape':
        e.preventDefault();
        e.stopPropagation();
        this._viewer._featureInteraction?.closePopup();
        this._viewer.focus();
        break;
      default:
        break;
    }
  }

  // --- Popup skip-button navigation (built by FeatureInteraction.openPopup) ---

  // Popup "‹" / "›": clamp to the previous/next feature (no wrap, matching
  // MapML.js _previousFeature/_nextFeature), close the popup, focus the target.
  previousFeature(featureEl) {
    const i = this._sorted.findIndex((e) => e.featureEl === featureEl);
    if (i < 0) return;
    this._viewer._featureInteraction?.closePopup();
    this._focusEntry(Math.max(i - 1, 0));
  }

  nextFeature(featureEl) {
    const i = this._sorted.findIndex((e) => e.featureEl === featureEl);
    if (i < 0) return;
    this._viewer._featureInteraction?.closePopup();
    this._focusEntry(Math.min(i + 1, this._sorted.length - 1));
  }

  // Popup "|‹": close the popup and return focus to the map.
  focusMap() {
    this._viewer._featureInteraction?.closePopup();
    this._viewer.focus();
  }

  // Popup "›|": close the popup and focus the first visible control (matches
  // MapML.js's `_controlContainer.querySelector('A:not([hidden])').focus()`).
  focusControls() {
    this._viewer._featureInteraction?.closePopup();
    const control = this._viewer._container.querySelector(
      '.ol-control button:not([hidden]), .ol-control a:not([hidden]), .ol-control input:not([hidden])'
    );
    control?.focus();
  }
}
