/**
 * Builds the per-layer `<fieldset>` for the layer control. Ported from
 * MapML.js's `createLayerControlForLayer.js` (`createLayerControlHTML`), kept as
 * its own module so the two implementations diff 1:1.
 *
 * Mirrors the DOM shape and event handling of the MapML.js original: checkbox
 * -> visibility, remove, settings toggle, opacity, and nested `<map-extent>`
 * sublayers. Legend links, alternate styles, disabled state and drag-reorder
 * are deferred.
 */
import { nextControlId, settingsControlSvg } from './layerControlUtils.js';

export function createLayerControlForLayer(layerEl, locale) {
  const fieldset = document.createElement('fieldset');
  fieldset.className = 'mapml-layer-item';
  fieldset.setAttribute('aria-grabbed', 'false');

  const properties = document.createElement('div');
  properties.className = 'mapml-layer-item-properties';
  fieldset.appendChild(properties);

  const settings = document.createElement('div');
  settings.className = 'mapml-layer-item-settings';
  settings.hidden = !layerEl._settingsExpanded;
  fieldset.appendChild(settings);

  // Toggle: checkbox + name
  const toggleLabel = document.createElement('label');
  toggleLabel.className = 'mapml-layer-item-toggle';
  properties.appendChild(toggleLabel);

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.className = 'leaflet-control-layers-selector';
  checkbox.checked = layerEl.checked;
  checkbox.addEventListener('change', () => {
    // Reflecting `checked` toggles group visibility via
    // attributeChangedCallback; `map-change` is the user-interaction signal
    // (MapML.js's changeCheck contract), distinct from programmatic writes.
    layerEl.checked = checkbox.checked;
    layerEl.dispatchEvent(new CustomEvent('map-change'));
  });
  toggleLabel.appendChild(checkbox);

  const nameSpan = document.createElement('span');
  nameSpan.className = 'mapml-layer-item-name';
  const nameId = `mapml-layer-item-name-${nextControlId()}`;
  nameSpan.id = nameId;
  // textContent (not innerHTML) so a malicious label can't inject markup.
  nameSpan.textContent = layerEl.label;
  fieldset.setAttribute('aria-labelledby', nameId);
  toggleLabel.appendChild(nameSpan);

  // Controls: remove + settings buttons
  const controls = document.createElement('div');
  controls.className = 'mapml-layer-item-controls';
  properties.appendChild(controls);

  const removeBtn = document.createElement('button');
  removeBtn.type = 'button';
  removeBtn.className = 'mapml-layer-item-remove-control mapml-button';
  removeBtn.title = locale.lmRemoveLayer;
  removeBtn.innerHTML = "<span aria-hidden='true'>&#10005;</span>";
  removeBtn.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    layerEl.remove();
  });
  controls.appendChild(removeBtn);

  const settingsBtn = document.createElement('button');
  settingsBtn.type = 'button';
  settingsBtn.className = 'mapml-layer-item-settings-control mapml-button';
  settingsBtn.title = locale.lmLayerSettings;
  settingsBtn.setAttribute('aria-expanded', String(layerEl._settingsExpanded));
  const iconHost = document.createElement('span');
  iconHost.className = 'mapml-button-icon';
  iconHost.setAttribute('aria-hidden', 'true');
  iconHost.appendChild(settingsControlSvg());
  settingsBtn.appendChild(iconHost);
  settingsBtn.addEventListener('click', () => {
    const willOpen = Boolean(settings.hidden);
    settings.hidden = !willOpen;
    layerEl._settingsExpanded = willOpen;
    settingsBtn.setAttribute('aria-expanded', String(willOpen));
  });
  controls.appendChild(settingsBtn);

  // Opacity control
  const opacityDetails = document.createElement('details');
  opacityDetails.className = 'mapml-layer-item-opacity mapml-control-layers';
  settings.appendChild(opacityDetails);

  const opacitySummary = document.createElement('summary');
  opacitySummary.textContent = locale.lcOpacity;
  const summaryId = `mapml-layer-item-opacity-${nextControlId()}`;
  opacitySummary.id = summaryId;
  opacityDetails.appendChild(opacitySummary);

  const opacitySlider = document.createElement('input');
  opacitySlider.type = 'range';
  opacitySlider.min = '0';
  opacitySlider.max = '1';
  opacitySlider.step = '0.1';
  opacitySlider.value = String(layerEl.getLayerGroup().getOpacity());
  opacitySlider.setAttribute('aria-labelledby', summaryId);
  opacitySlider.addEventListener('input', () => {
    layerEl.setOpacity(Number(opacitySlider.value));
  });
  opacityDetails.appendChild(opacitySlider);

  // Alternate-style radio group (rel=style / self style). Ported from MapML.js
  // layer.js `getAlternateStyles`: only emitted when a layer advertises two or
  // more style links. For a remote layer they live in the shadow root.
  const styleRoot = layerEl.src ? layerEl.shadowRoot : layerEl;
  const styleLinks = styleRoot
    ? styleRoot.querySelectorAll(
        'map-link[rel=style],map-link[rel="self style"],map-link[rel="style self"]'
      )
    : [];
  if (styleLinks.length > 1) {
    const stylesControl = document.createElement('details');
    stylesControl.className = 'mapml-layer-item-style mapml-control-layers';
    const stylesSummary = document.createElement('summary');
    stylesSummary.textContent = locale.lmStyle;
    stylesControl.appendChild(stylesSummary);
    for (const link of styleLinks) {
      const option = link.getLayerControlOption();
      if (option) stylesControl.appendChild(option);
    }
    settings.appendChild(stylesControl);
  }

  // Grouped extents (sublayers) fieldset
  const extentsFieldset = document.createElement('fieldset');
  extentsFieldset.className = 'mapml-layer-grouped-extents';
  extentsFieldset.setAttribute('aria-label', 'Sublayers');
  let visibleExtentCount = 0;
  for (const ext of layerEl.querySelectorAll(':scope > map-extent')) {
    if (ext.hasAttribute('hidden')) {
      continue;
    }
    extentsFieldset.appendChild(ext.getLayerControlHTML(locale));
    visibleExtentCount += 1;
  }
  if (visibleExtentCount === 0) {
    extentsFieldset.setAttribute('hidden', '');
  }
  settings.appendChild(extentsFieldset);

  return fieldset;
}
