/**
 * Stylesheet for the {@link GeolocationButton} bottom-right control and its
 * user-location marker. The 40×40 button chrome matches the other custom
 * controls in this port (see fullscreenButton.css.js); it is pinned above the
 * bottom-right attribution disclosure. The location dot + permanent tooltip are
 * plain DOM in `ol/Overlay`s (the accuracy circle is a vector feature styled in
 * the control), so they are styled here.
 */
export const geolocationButtonCss = /* css */ `
.mapml-geolocation-button {
  right: .5em;
  bottom: calc(.5em + 34px);
  padding: 0;
  background-color: #fff;
  border: 1px solid #e3e3e3;
  border-radius: 4px;
  box-shadow: rgb(0 0 0 / 30%) 0px 1px 4px -1px;
}

.mapml-geolocation-button button.mapml-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin: 0;
  padding: 0;
  background-color: #fff;
  border: none;
  border-radius: 4px;
  color: #000;
  cursor: pointer;
}

/* State-tinted arrow, matching leaflet.locatecontrol / MapML.js / MapML-MapLibre:
   OFF = black (base), FOLLOWING = orange, BACKGROUND (last-known) = blue. */
.mapml-geolocation-button button.mapml-geolocation-following {
  color: #fc8428;
}
.mapml-geolocation-button button.mapml-geolocation-background {
  color: #2074b6;
}

/* Drop ol.css's gray hover/focus outline and draw the shared focus ring. */
.mapml-geolocation-button > button:hover,
.mapml-geolocation-button > button:focus:not(:focus-visible) {
  outline: none;
}
.mapml-geolocation-button > button:focus-visible {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: 1px;
}

/* User-location dot: a blue disc with a white ring (Leaflet/MapLibre look). */
.mapml-location-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: #2d8cff;
  border: 3px solid #fff;
  box-shadow: 0 0 3px rgb(0 0 0 / 35%);
  box-sizing: border-box;
  cursor: default;
}
.mapml-location-dot:focus-visible {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: 2px;
}

/* Permanent tooltip shown above the dot while following. */
.mapml-location-tooltip {
  padding: 2px 6px;
  background-color: #fff;
  border: 1px solid #e3e3e3;
  border-radius: 4px;
  box-shadow: rgb(0 0 0 / 30%) 0px 1px 4px -1px;
  font-size: 12px;
  line-height: 1.4;
  white-space: nowrap;
  color: #222;
  pointer-events: none;
}
`;
