/**
 * `StaticButton` — opt-in (`controlslist="static"`) top-right control that
 * toggles the viewer's `static` attribute (freezing/thawing map interaction).
 * Ported from MapML.js `src/mapml/control/StaticButton.js` (a Leaflet `Control`)
 * to an OpenLayers `ol/control/Control`.
 *
 * The button drives the viewer through its public `static` setter; the viewer's
 * `attributeChangedCallback` owns the mechanics (disabling the OL interactions
 * and the zoom control). A `MutationObserver` on the viewer's `static`
 * attribute keeps the button's icon + `aria-pressed` in sync with programmatic
 * / attribute-driven changes, exactly like MapML.js.
 *
 * Icons are the Material Symbols `lock` (static ON — frozen) / `lock_open`
 * (static OFF — interactive), inlined with `fill="currentColor"` so the button
 * `color` tints them.
 */
import Control from 'ol/control/Control.js';

// Material Symbols `lock` (static ON — map interaction is frozen).
const LOCK_SVG =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="24" width="24" viewBox="0 -960 960 960" fill="currentColor">' +
  '<path d="M240-80q-33 0-56.5-23.5T160-160v-400q0-33 23.5-56.5T240-640h40v-80q0-83 58.5-141.5T480-920q83 0 141.5 58.5T680-720v80h40q33 0 56.5 23.5T800-560v400q0 33-23.5 56.5T720-80H240Zm0-80h480v-400H240v400Zm296.5-143.5Q560-327 560-360t-23.5-56.5Q513-440 480-440t-56.5 23.5Q400-393 400-360t23.5 56.5Q447-280 480-280t56.5-23.5ZM360-640h240v-80q0-50-35-85t-85-35q-50 0-85 35t-35 85v80ZM240-160v-400 400Z"/>' +
  '</svg>';

// Material Symbols `lock_open` (static OFF — map is interactive).
const LOCK_OPEN_SVG =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="24" width="24" viewBox="0 -960 960 960" fill="currentColor">' +
  '<path d="M240-160h480v-400H240v400Zm296.5-143.5Q560-327 560-360t-23.5-56.5Q513-440 480-440t-56.5 23.5Q400-393 400-360t23.5 56.5Q447-280 480-280t56.5-23.5ZM240-160v-400 400Zm0 80q-33 0-56.5-23.5T160-160v-400q0-33 23.5-56.5T240-640h280v-80q0-83 58.5-141.5T720-920q83 0 141.5 58.5T920-720h-80q0-50-35-85t-85-35q-50 0-85 35t-35 85v80h120q33 0 56.5 23.5T800-560v400q0 33-23.5 56.5T720-80H240Z"/>' +
  '</svg>';

export class StaticButton extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-static-button ol-control';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';
    container.appendChild(button);

    super({ element: container });

    this._viewer = viewer;
    this._button = button;

    // Drive the viewer through its public `static` setter; the viewer's
    // attribute observer owns disabling the interactions + zoom control.
    this._onClick = (event) => {
      event.stopPropagation();
      viewer.static = !viewer.static;
    };
    button.addEventListener('click', this._onClick);

    // Reflect programmatic / attribute-driven changes to the viewer's `static`
    // attribute back onto the button (icon + aria-pressed).
    this._staticObserver = new MutationObserver(() => this._update());
    this._staticObserver.observe(viewer, {
      attributes: true,
      attributeFilter: ['static']
    });

    this._update();
  }

  destroy() {
    this._button.removeEventListener('click', this._onClick);
    this._staticObserver?.disconnect();
    this._staticObserver = null;
  }

  _update() {
    const isStatic = this._viewer.hasAttribute('static');
    const label = this._viewer.locale.btnStatic;
    this._button.title = label;
    this._button.setAttribute('aria-label', label);
    this._button.setAttribute('aria-pressed', String(isStatic));
    this._button.innerHTML = isStatic ? LOCK_SVG : LOCK_OPEN_SVG;
  }
}
